import { mkdir, readdir, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

interface LogEntry {
	sessionId: string;
	level: string;
	message: string;
	timestamp: string;
	caller?: string;
	sequence: number;
}

interface BatchLogRequest {
	logs: LogEntry[];
}

const cleanupEnabled = false;

// Track if we've already cleaned up old logs for this session
const cleanedSessions = new Set<string>();

// Buffer to store out-of-order log entries per session
const logBuffers = new Map<
	string,
	{ entries: LogEntry[]; nextSequence: number; writeLock: Promise<void> }
>();

async function cleanupOldClientLogs(
	logsDir: string,
	sessionId: string,
): Promise<void> {
	// Check if cleanup is enabled (default: false to keep logs)
	if (!cleanupEnabled) return;

	// Only cleanup once per session
	if (cleanedSessions.has(sessionId)) return;

	try {
		// Ensure logs directory exists
		await mkdir(logsDir, { recursive: true });

		// Read all files in the logs directory
		const files = await readdir(logsDir);

		// Find all client log files (files starting with 'client_')
		const clientLogFiles = files.filter((file) => file.startsWith("client_"));

		// Delete all previous client log files
		const deletePromises = clientLogFiles.map((file) =>
			unlink(join(logsDir, file)).catch(() => {
				// Silently ignore deletion errors
			}),
		);

		await Promise.all(deletePromises);

		// Mark this session as cleaned up
		cleanedSessions.add(sessionId);
	} catch {
		// Silently fail to avoid infinite loops
	}
}

async function writeLogEntry(
	logEntry: LogEntry,
	logsDir: string,
): Promise<void> {
	const { sessionId } = logEntry;

	// Get or create buffer for this session
	let buffer = logBuffers.get(sessionId);
	if (!buffer) {
		logBuffers.set(sessionId, {
			entries: [],
			nextSequence: 1,
			writeLock: Promise.resolve(),
		});
	}

	buffer = logBuffers.get(sessionId);
	if (!buffer) return;

	// Add entry to buffer
	buffer.entries.push(logEntry);

	// Sort buffer by sequence number
	buffer.entries.sort((a, b) => a.sequence - b.sequence);

	// Wait for any pending writes to complete
	await buffer.writeLock;

	// Create a new write lock promise
	let resolveWriteLock: (() => void) | undefined;
	buffer.writeLock = new Promise((resolve) => {
		resolveWriteLock = resolve;
	});

	try {
		// Write all consecutive entries starting from nextSequence
		const logFileName = `client_${sessionId}.log`;
		const logFilePath = join(logsDir, logFileName);

		while (buffer.entries.length > 0) {
			const firstEntry = buffer.entries[0];
			if (!firstEntry) break;

			// If the sequence is newer (gap detected or server restarted), fast-forward nextSequence to match it
			if (firstEntry.sequence > buffer.nextSequence) {
				buffer.nextSequence = firstEntry.sequence;
			}

			// If the sequence is what we expect, write it
			if (firstEntry.sequence === buffer.nextSequence) {
				const entry = buffer.entries.shift();
				if (!entry) break;
				const logLine = `[${entry.timestamp}] [${entry.level.toUpperCase()}] [SEQ:${entry.sequence}] [${
					entry.caller || "unknown"
				}] ${entry.message}\n`;

				await writeFile(logFilePath, logLine, { flag: "a" });
				buffer.nextSequence++;
			}
			// If the sequence is older than what we expect, write it anyway (out-of-order recovery)
			else {
				const entry = buffer.entries.shift();
				if (!entry) break;
				const logLine = `[${entry.timestamp}] [${entry.level.toUpperCase()}] [SEQ:${entry.sequence}] [${
					entry.caller || "unknown"
				}] ${entry.message}\n`;

				await writeFile(logFilePath, logLine, { flag: "a" });
			}
		}
	} finally {
		if (resolveWriteLock) resolveWriteLock();
	}
}

async function writeBatchLogs(
	logs: LogEntry[],
	logsDir: string,
): Promise<void> {
	// Group logs by sessionId
	const logsBySession = new Map<string, LogEntry[]>();

	for (const log of logs) {
		if (!logsBySession.has(log.sessionId)) {
			logsBySession.set(log.sessionId, []);
		}
		logsBySession.get(log.sessionId)?.push(log);
	}

	// Write each session's logs
	for (const [sessionId, sessionLogs] of logsBySession) {
		// Clean up old logs for this session
		await cleanupOldClientLogs(logsDir, sessionId);

		// Write all logs for this session
		for (const log of sessionLogs) {
			await writeLogEntry(log, logsDir);
		}
	}
}

export async function POST(request: NextRequest) {
	// Only allow in development
	if (process.env.NODE_ENV !== "development") {
		return NextResponse.json({ error: "Not found" }, { status: 404 });
	}

	try {
		const body = (await request.json()) as BatchLogRequest;

		// Check if this is a batch request
		if (Array.isArray(body.logs)) {
			// Validate that all entries have required fields
			for (const logEntry of body.logs) {
				if (
					!logEntry.sessionId ||
					!logEntry.level ||
					!logEntry.message ||
					typeof logEntry.sequence !== "number"
				) {
					return NextResponse.json(
						{ error: "Missing required fields in log entry" },
						{ status: 400 },
					);
				}
			}

			// Create logs directory if it doesn't exist
			const logsDir = join(process.cwd(), "logs");
			try {
				await mkdir(logsDir, { recursive: true });
			} catch {
				// Directory might already exist, ignore error
			}

			// Write batch logs
			await writeBatchLogs(body.logs, logsDir);

			return NextResponse.json({ success: true, count: body.logs.length });
		}

		// If not a batch request, return error
		return NextResponse.json(
			{ error: "Invalid request format. Expected { logs: LogEntry[] }" },
			{ status: 400 },
		);
	} catch {
		// Use a simple error response without logging to avoid potential issues
		return NextResponse.json(
			{ error: "Failed to write logs" },
			{ status: 500 },
		);
	}
}

import { createReadStream, statSync } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { type NextRequest, NextResponse } from "next/server";
import logger from "@/backend/lib/logger";
import { extToMime } from "@/utils/storage.utils";

// import { extractTokenFromHeader, verifyToken } from "@/backend/lib/auth/jwt";
// import { StorageDbRepository } from "@/backend/db/repo/storage.repository";

const storagePath = process.env.LOCAL_STORAGE_PATH || "./storage/";

/**
 * Convert relative user path to secure absolute filesystem path
 * Prevents path traversal attacks
 */
function getAbsolutePath(relativePath: string): string {
	const basePath = path.resolve(process.cwd(), storagePath);
	const resolvedPath = path.resolve(basePath, relativePath);
	const relativeToBase = path.relative(basePath, resolvedPath);

	if (relativeToBase.startsWith("..") || path.isAbsolute(relativeToBase)) {
		throw new Error("Path traversal detected");
	}

	return resolvedPath;
}

/**
 * Detect content type from file extension
 */
function getContentType(filePath: string): string {
	const ext = path.extname(filePath).toLowerCase().replace(".", "");
	return extToMime[ext] || "application/octet-stream";
}

/**
 * Parse range header
 */
function parseRange(
	rangeHeader: string,
	fileSize: number,
): { start: number; end: number } | null {
	const match = rangeHeader.match(/bytes=(\d+)-(\d*)/);
	if (!match?.[1]) return null;

	const start = Number.parseInt(match[1], 10);
	const end = match[2] ? Number.parseInt(match[2], 10) : fileSize - 1;

	if (start >= fileSize || end >= fileSize || start > end) {
		return null;
	}

	return { start, end };
}

/**
 * Handle file downloads and streaming
 * GET /api/storage/files/[[...path]]
 */
export async function GET(
	request: NextRequest,
	{ params }: { params: Promise<{ path?: string[] }> },
) {
	try {
		// Step 1: Await params and reconstruct relative file path
		const resolvedParams = await params;
		const relativePath = resolvedParams.path
			? resolvedParams.path.join("/")
			: "";

		if (!relativePath) {
			return NextResponse.json(
				{ error: "File path is required" },
				{ status: 400 },
			);
		}

		// Step 2: Secure path resolution
		let absolutePath: string;
		try {
			absolutePath = getAbsolutePath(relativePath);
		} catch (error) {
			logger.warn("Path traversal attempt detected", {
				path: relativePath,
				error: error instanceof Error ? error.message : String(error),
			});
			return NextResponse.json({ error: "Invalid file path" }, { status: 400 });
		}

		// Step 3: Check if file exists
		try {
			await fs.access(absolutePath);
		} catch {
			logger.warn("File not found", { path: relativePath });
			return NextResponse.json({ error: "File not found" }, { status: 404 });
		}

		// Step 4: Check permissions (commented out - privacy not implemented in local storage yet)
		// const dbFile = await StorageDbRepository.fileByPath(relativePath);

		// TODO: Implement privacy/access control for files
		// Currently isProtected only prevents deletion, not access
		// Uncomment below when privacy feature is implemented in local storage adapter
		/*
    // If file is protected, verify authentication
    if (dbFile?.isProtected) {
      const authHeader = request.headers.get("authorization");
      const accessToken = extractTokenFromHeader(authHeader);
      const payload = accessToken ? await verifyToken(accessToken) : null;

      if (!payload || payload.type !== "access") {
        logger.warn("Unauthorized access to protected file", {
          path: relativePath,
        });
        return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
      }
    }

    // Check parent directory permissions
    const parentPath = relativePath.substring(0, relativePath.lastIndexOf("/"));
    if (parentPath) {
      const parentDir = await StorageDbRepository.directoryByPath(parentPath);
      if (parentDir && parentDir.protectChildren) {
        const authHeader = request.headers.get("authorization");
        const accessToken = extractTokenFromHeader(authHeader);
        const payload = accessToken ? await verifyToken(accessToken) : null;

        if (!payload || payload.type !== "access") {
          logger.warn("Unauthorized access to file in protected directory", {
            path: relativePath,
            parentPath,
          });
          return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
        }
      }
    }
    */

		// Step 5: Get file stats
		const stats = statSync(absolutePath);
		const fileSize = stats.size;
		const contentType = getContentType(relativePath);

		// Step 6: Handle range requests
		const rangeHeader = request.headers.get("range");

		if (rangeHeader) {
			const range = parseRange(rangeHeader, fileSize);

			if (!range) {
				return new NextResponse(null, {
					status: 416,
					headers: {
						"Content-Range": `bytes */${fileSize}`,
					},
				});
			}

			const { start, end } = range;
			const chunkSize = end - start + 1;
			const stream = createReadStream(absolutePath, { start, end });

			logger.info("Streaming partial content", {
				path: relativePath,
				start,
				end,
				chunkSize,
			});

			return new NextResponse(stream as unknown as BodyInit, {
				status: 206,
				headers: {
					"Content-Type": contentType,
					"Content-Length": chunkSize.toString(),
					"Content-Range": `bytes ${start}-${end}/${fileSize}`,
					"Accept-Ranges": "bytes",
					"Cache-Control": "public, max-age=31536000, immutable",
					"Last-Modified": stats.mtime.toUTCString(),
				},
			});
		}

		// Step 7: Stream full file
		const stream = createReadStream(absolutePath);

		logger.info("Streaming full file", {
			path: relativePath,
			size: fileSize,
		});

		return new NextResponse(stream as unknown as BodyInit, {
			status: 200,
			headers: {
				"Content-Type": contentType,
				"Content-Length": fileSize.toString(),
				"Accept-Ranges": "bytes",
				"Cache-Control": "public, max-age=31536000, immutable",
				"Last-Modified": stats.mtime.toUTCString(),
			},
		});
	} catch (error) {
		logger.error("Unexpected error in file serving handler", {
			error: error instanceof Error ? error.message : String(error),
			stack: error instanceof Error ? error.stack : undefined,
		});

		return NextResponse.json(
			{ error: "Internal server error" },
			{ status: 500 },
		);
	}
}

import { createWriteStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import crypto from "crypto";
import { type NextRequest, NextResponse } from "next/server";
import { SignedUrlRepository } from "@/backend/db/repo";
import { StorageDbRepository } from "@/backend/db/repo/storage.repository";
import logger from "@/backend/lib/logger";
import { NEXT_PUBLIC_BASE_URL } from "@/backend/lib/server";

const storagePath = process.env.LOCAL_STORAGE_PATH || "./storage/";

/**
 * Convert relative user path to secure absolute filesystem path
 * Prevents path traversal attacks
 */
function getAbsolutePath(relativePath: string): string {
	const basePath = path.resolve(process.cwd(), storagePath);
	const resolvedPath = path.resolve(basePath, relativePath);
	const relativeToBase = path.relative(basePath, resolvedPath);

	if (relativeToBase.startsWith("..") || path.isAbsolute(relativeToBase)) {
		throw new Error("Path traversal detected");
	}

	return resolvedPath;
}

/**
 * Stream request body to file while calculating MD5
 */
async function streamToFile(
	stream: ReadableStream<Uint8Array>,
	filePath: string,
	expectedMd5: string,
): Promise<void> {
	const hash = crypto.createHash("md5");
	const writeStream = createWriteStream(filePath);
	const reader = stream.getReader();

	try {
		while (true) {
			const { done, value } = await reader.read();
			if (done) break;

			hash.update(value);
			await new Promise<void>((resolve, reject) => {
				writeStream.write(value, (err: Error | null | undefined) => {
					if (err) reject(err);
					else resolve();
				});
			});
		}

		await new Promise<void>((resolve, reject) => {
			writeStream.end((err: Error | null | undefined) => {
				if (err) reject(err);
				else resolve();
			});
		});

		const actualMd5 = hash.digest("base64");
		if (actualMd5 !== expectedMd5) {
			await fs.unlink(filePath);
			throw new Error("MD5 hash mismatch");
		}
	} catch (error) {
		try {
			await fs.unlink(filePath);
		} catch {
			// Ignore cleanup errors
		}
		throw error;
	}
}

/**
 * Handle signed URL file uploads
 * PUT /api/storage/upload/[id]
 */
export async function PUT(
	request: NextRequest,
	{ params }: { params: Promise<{ id: string }> },
) {
	try {
		const { id: tokenId } = await params;

		// Step 1: Atomically claim the token
		const signedUrl = await SignedUrlRepository.claimSignedUrl(tokenId);

		if (!signedUrl) {
			logger.warn("Invalid or expired signed URL token", { tokenId });
			return NextResponse.json(
				{ error: "Invalid, expired, or already used token" },
				{ status: 403 },
			);
		}

		logger.info("🔍 [API DEBUG] Claimed signed URL", {
			tokenId,
			expectedContentType: signedUrl.contentType,
			expectedFileSize: signedUrl.fileSize.toString(),
			expectedContentMd5: signedUrl.contentMd5,
			filePath: signedUrl.filePath,
		});

		// Step 2: Validate metadata headers
		const contentType = request.headers.get("content-type");
		const contentLength = request.headers.get("content-length");
		const contentMd5 = request.headers.get("content-md5");

		logger.info("🔍 [API DEBUG] Received upload request headers", {
			tokenId,
			receivedContentType: contentType,
			receivedContentLength: contentLength,
			receivedContentMd5: contentMd5,
		});

		if (contentType !== signedUrl.contentType) {
			logger.warn("🔍 [API DEBUG] Content-Type mismatch", {
				tokenId,
				expected: signedUrl.contentType,
				received: contentType,
				match: contentType === signedUrl.contentType,
			});
			return NextResponse.json(
				{
					error: `Content-Type mismatch. Expected: ${signedUrl.contentType}`,
				},
				{ status: 400 },
			);
		}

		if (contentLength && BigInt(contentLength) > signedUrl.fileSize) {
			logger.warn("Content-Length exceeds declared size", {
				tokenId,
				expected: signedUrl.fileSize.toString(),
				received: contentLength,
			});
			return NextResponse.json(
				{
					error: `Content-Length exceeds declared size of ${signedUrl.fileSize} bytes`,
				},
				{ status: 413 },
			);
		}

		if (!contentMd5) {
			logger.warn("Missing Content-MD5 header", { tokenId });
			return NextResponse.json(
				{ error: "Content-MD5 header is required" },
				{ status: 400 },
			);
		}

		if (contentMd5 !== signedUrl.contentMd5) {
			logger.warn("Content-MD5 mismatch", {
				tokenId,
				expected: signedUrl.contentMd5,
				received: contentMd5,
			});
			return NextResponse.json(
				{
					error: "Content-MD5 mismatch",
				},
				{ status: 400 },
			);
		}

		// Step 3: Secure path resolution
		let absolutePath: string;
		try {
			absolutePath = getAbsolutePath(signedUrl.filePath);
		} catch (error) {
			logger.error("Path traversal attempt detected", {
				tokenId,
				path: signedUrl.filePath,
				error: error instanceof Error ? error.message : String(error),
			});
			return NextResponse.json({ error: "Invalid file path" }, { status: 400 });
		}

		// Step 4: Ensure parent directory exists
		await fs.mkdir(path.dirname(absolutePath), {
			recursive: true,
			mode: 0o755,
		});

		// Step 5: Stream to disk with MD5 verification
		if (!request.body) {
			return NextResponse.json(
				{ error: "Request body is required" },
				{ status: 400 },
			);
		}

		try {
			await streamToFile(request.body, absolutePath, signedUrl.contentMd5);
		} catch (error) {
			logger.error("Failed to stream file to disk", {
				tokenId,
				path: signedUrl.filePath,
				error: error instanceof Error ? error.message : String(error),
			});
			return NextResponse.json(
				{
					error:
						error instanceof Error ? error.message : "Failed to write file",
				},
				{ status: 400 },
			);
		}

		// Step 6: Create file record with transaction safety
		try {
			const fileEntity = await StorageDbRepository.createFile(
				signedUrl.filePath,
				false,
			);

			const stats = await fs.stat(absolutePath);
			const baseUrl = NEXT_PUBLIC_BASE_URL || "http://localhost:3000";

			logger.info("🔍 [API DEBUG] File uploaded successfully via signed URL", {
				tokenId,
				path: signedUrl.filePath,
				absolutePath,
				size: stats.size,
				fileExistsOnDisk: true,
			});

			return NextResponse.json(
				{
					id: fileEntity.id.toString(),
					path: signedUrl.filePath,
					size: stats.size,
					contentType: signedUrl.contentType,
					url: `${baseUrl}/api/storage/files/${signedUrl.filePath}`,
					createdAt: stats.birthtime.toISOString(),
					isProtected: fileEntity.isProtected,
				},
				{ status: 201 },
			);
		} catch (error) {
			// Database insert failed - delete orphaned file
			try {
				await fs.unlink(absolutePath);
			} catch {
				// Ignore cleanup errors
			}

			logger.error("Failed to create file record", {
				tokenId,
				path: signedUrl.filePath,
				error: error instanceof Error ? error.message : String(error),
			});

			return NextResponse.json(
				{ error: "Failed to create file record" },
				{ status: 500 },
			);
		}
	} catch (error) {
		logger.error("Unexpected error in upload handler", {
			error: error instanceof Error ? error.message : String(error),
			stack: error instanceof Error ? error.stack : undefined,
		});

		return NextResponse.json(
			{ error: "Internal server error" },
			{ status: 500 },
		);
	}
}

import { type HandleUploadBody, handleUpload } from "@vercel/blob/client";
import { type NextRequest, NextResponse } from "next/server";
import { SignedUrlRepository, StorageDbRepository } from "@/backend/db/repo";
import { extractTokenFromHeader, verifyToken } from "@/backend/lib/auth/jwt";
import logger from "@/backend/lib/logger";
import { StorageUtils } from "@/backend/utils";

export type VercelUploadUrlClientPlayload = {
	sessionId: string;
	fileSize: number;
	contentType: string;
};

/**
 * Handle Vercel Blob client SDK upload requests
 * POST /api/storage/vercel-upload
 */
export async function POST(request: NextRequest): Promise<NextResponse> {
	try {
		// Step 1: Authenticate the request (same pattern as GraphQL context)
		const authHeader = request.headers.get("authorization");
		const accessToken = extractTokenFromHeader(authHeader);

		let userId: number | null = null;

		if (accessToken) {
			const payload = await verifyToken(accessToken);
			if (payload && payload.type === "access") {
				userId = payload.userId;
			}
		}

		// Require authentication for uploads
		if (!userId) {
			logger.warn("Unauthorized upload attempt");
			return NextResponse.json(
				{ error: "Authentication required" },
				{ status: 401 },
			);
		}

		logger.info("🔍 [VERCEL UPLOAD] Request authenticated", {
			userId,
			authenticated: !!userId,
		});

		// Step 2: Parse request body from Vercel SDK
		const body = (await request.json()) as HandleUploadBody;
		if (body.type !== "blob.generate-client-token") {
			throw new Error("InvalidEventType");
		}

		const clientPlayload: VercelUploadUrlClientPlayload = body.payload
			.clientPayload
			? (JSON.parse(
					body.payload.clientPayload,
				) as VercelUploadUrlClientPlayload)
			: ({} as VercelUploadUrlClientPlayload);
		const pathName = body.payload.pathname;
		if (!pathName) {
			logger.warn("Missing pathname in upload request", {
				userId,
			});
			return NextResponse.json(
				{ error: "Missing pathname in upload request" },
				{ status: 400 },
			);
		}

		const { sessionId, fileSize, contentType } = clientPlayload;
		if (!sessionId) {
			logger.warn("Missing upload session ID", {
				pathname: pathName,
			});
			return NextResponse.json(
				{ error: "Missing upload session ID" },
				{ status: 400 },
			);
		}

		if (!fileSize || fileSize <= 0) {
			logger.warn("Invalid file size in upload request", {
				pathname: pathName,
				fileSize,
			});
			return NextResponse.json(
				{ error: "Invalid file size in upload request" },
				{ status: 400 },
			);
		}

		if (!contentType) {
			logger.warn("Missing content type in upload request", {
				pathname: pathName,
			});
			return NextResponse.json(
				{ error: "Missing content type in upload request" },
				{ status: 400 },
			);
		}

		logger.info("🔍 [VERCEL UPLOAD] Received upload request", {
			pathname: body.payload.pathname,
			type: contentType,
			userId,
		});

		// Step 3: Validate upload request
		const validationError = await StorageUtils.validateUpload(
			pathName,
			fileSize,
			contentType,
		);

		if (validationError) {
			logger.warn("Upload validation failed", {
				pathname: pathName,
				error: validationError,
			});
			return NextResponse.json({ error: validationError }, { status: 400 });
		}

		// Step 4: Check directory permissions
		const directoryPath = pathName.substring(0, pathName.lastIndexOf("/"));
		const dbDirectory =
			await StorageDbRepository.directoryByPath(directoryPath);

		if (dbDirectory && !dbDirectory.allowUploads) {
			logger.warn("Uploads not allowed in directory", {
				pathname: pathName,
				directory: directoryPath,
			});
			return NextResponse.json(
				{ error: "Uploads not allowed in this directory" },
				{ status: 403 },
			);
		}

		// Step 6: Validate existing session
		const session = await SignedUrlRepository.getSignedUrlById(sessionId);

		if (!session) {
			logger.warn("Invalid upload session", {
				sessionId,
				pathname: pathName,
			});
			return NextResponse.json(
				{ error: "Invalid upload session" },
				{ status: 403 },
			);
		}

		if (session.used) {
			logger.warn("Upload session already used", {
				sessionId,
				pathname: pathName,
			});
			return NextResponse.json(
				{ error: "Upload session already used" },
				{ status: 403 },
			);
		}

		if (session.expiresAt < new Date()) {
			logger.warn("Upload session expired", {
				sessionId,
				pathname: pathName,
				expiresAt: session.expiresAt,
			});
			return NextResponse.json(
				{ error: "Upload session expired" },
				{ status: 403 },
			);
		}

		// Validate metadata matches
		if (session.filePath !== pathName) {
			logger.warn("File path mismatch", {
				sessionId,
				expectedPath: session.filePath,
				receivedPath: pathName,
			});
			return NextResponse.json(
				{ error: "File path mismatch" },
				{ status: 400 },
			);
		}

		logger.info("🔍 [VERCEL UPLOAD] Validated upload session", {
			sessionId,
			pathname: pathName,
			expiresAt: session.expiresAt,
		});

		// Step 7: Use Vercel's handleUpload to generate upload URL
		const jsonResponse = await handleUpload({
			body,
			request,
			onBeforeGenerateToken: async () => {
				// Additional validation before token generation
				logger.info("🔍 [VERCEL UPLOAD] Generating token", {
					pathname: pathName,
				});

				// Return metadata to attach to the blob
				return {
					allowOverwrite: true,
					allowedContentTypes: [contentType],
					tokenPayload: JSON.stringify({
						sessionId,
						pathname: pathName,
						userId,
					}),
				};
			},
			onUploadCompleted: async ({ blob, tokenPayload }) => {
				// This runs AFTER the upload completes
				logger.info("🔍 [VERCEL UPLOAD] Upload completed", {
					url: blob.url,
					pathname: blob.pathname,
				});

				try {
					// Parse token payload
					const rawPayload = JSON.parse(tokenPayload || "{}") as {
						sessionId?: string;
					};
					const sessionId = rawPayload.sessionId;

					// Mark session as used
					if (sessionId) {
						await SignedUrlRepository.claimSignedUrl(sessionId);
					}

					// Create file record in database
					await StorageDbRepository.createFile(blob.pathname);

					logger.info("✅ [VERCEL UPLOAD] File record created", {
						pathname: blob.pathname,
					});
				} catch (error) {
					logger.error("Failed to create file record after upload", {
						pathname: blob.pathname,
						error: error instanceof Error ? error.message : String(error),
					});
				}
			},
		});

		return NextResponse.json(jsonResponse);
	} catch (error) {
		logger.error("Unexpected error in Vercel upload handler", {
			error: error instanceof Error ? error.message : String(error),
			stack: error instanceof Error ? error.stack : undefined,
		});

		return NextResponse.json(
			{ error: "Internal server error" },
			{ status: 500 },
		);
	}
}

import { eq, inArray, sql } from "drizzle-orm";
import type { PgSelect } from "drizzle-orm/pg-core";
import { db } from "@/backend/db/drizzleDb";
import { queryWithPagination } from "@/backend/db/query.extensions";
import { students } from "@/backend/db/schema";
import type * as Types from "@/backend/types";
import {
	PaginationUtils,
	StudentFilterUtils,
	StudentUtils,
} from "@/backend/utils";

const _processStudentQuery = async <T extends PgSelect>(
	query: T,
	paginationArgs?: Types.PaginationArgs | null,
	orderBy?: Types.StudentsOrderByClause[] | null,
	filters?: Types.StudentFilterArgs | null,
): Promise<Types.StudentsWithFiltersResponse> => {
	let processedQuery = query;
	processedQuery = StudentFilterUtils.applyFilters(processedQuery, filters);
	processedQuery = StudentFilterUtils.applyOrdering(processedQuery, orderBy);
	processedQuery = queryWithPagination(processedQuery, paginationArgs);

	const results = await (processedQuery as unknown as Promise<
		{ student: Types.StudentEntity; total: number }[]
	>);

	const total = results[0]?.total ?? 0;
	const items: Types.StudentDto[] = results
		.map((r) => {
			const s: Types.StudentEntity = r.student;
			return StudentUtils.mapEntityToDto(s);
		})
		.filter((s): s is Types.StudentDto => s !== null);

	const pageInfo = PaginationUtils.buildPageInfoFromArgs(
		paginationArgs,
		items.length,
		total,
	);

	return {
		data: items,
		pageInfo: pageInfo,
	};
};

export namespace StudentRepository {
	export const findById = async (
		id: number,
	): Promise<Types.StudentEntity | null | undefined> => {
		return await db.query.students.findFirst({
			where: { id: id },
		});
	};

	export const create = async (
		input: Types.StudentCreateInput,
	): Promise<Types.StudentEntity> => {
		await StudentUtils.validateName(input.name).then((err) => {
			if (err) throw new Error(err);
		});

		const insertInput: Types.StudentEntityInput = {
			name: input.name,
			email: input.email?.value,
			phoneNumber: input.phoneNumber?.number,
			dateOfBirth: input.dateOfBirth,
			gender: input.gender,
			nationality: input.nationality,
			createdAt: new Date(),
			updatedAt: new Date(),
		};
		try {
			const [createdStudent] = await db
				.insert(students)
				.values(insertInput)
				.returning();
			return createdStudent;
		} catch {
			throw new Error("Failed to create student");
		}
	};

	export const createList = async (
		input: Types.StudentCreateInput[],
	): Promise<Types.StudentEntity[]> => {
		if (input.length === 0) return [];

		try {
			const result = await Promise.all(input.map((item) => create(item)));
			return result;
		} catch (error) {
			throw new Error(
				`Failed to create students: ${error instanceof Error ? error.message : "Unknown error"}`,
				{ cause: error },
			);
		}
	};

	export const loadByIds = async (
		ids: number[],
	): Promise<(Types.StudentDto | Error)[]> => {
		if (ids.length === 0) return [];

		const foundStudents = await db
			.select()
			.from(students)
			.where(inArray(students.id, ids));

		const studentList: (Types.StudentDto | Error)[] = ids.map((id) => {
			const s = foundStudents.find((c) => c.id === id);
			if (!s) return new Error(`Student ${id} not found`);
			return StudentUtils.mapEntityToDto(s) as Types.StudentDto;
		});
		return studentList;
	};

	export const existsById = async (id: number): Promise<boolean> => {
		return (await db.$count(students, eq(students.id, id))) > 0;
	};

	export const allExistsByIds = async (ids: number[]): Promise<boolean> => {
		return (
			(await db.$count(students, inArray(students.id, ids))) === ids.length
		);
	};

	export const countAllStudents = async (): Promise<number> => {
		return await db.$count(students);
	};

	export const deleteById = async (
		id: number,
	): Promise<Types.StudentEntity> => {
		const existingStudent = await findById(id);
		if (!existingStudent) {
			throw new Error(`Student ${id} not found`);
		}
		await db.delete(students).where(eq(students.id, id));
		return existingStudent;
	};

	export const partiallyUpdate = async (
		input: Types.PartialStudentUpdateInput,
	): Promise<Types.StudentEntity> => {
		const existingStudent = await findById(input.id);
		if (!existingStudent) {
			throw new Error(`Student ${input.id} not found`);
		}

		if (input.name) {
			const nameErr = await StudentUtils.validateName(input.name);
			if (nameErr) throw new Error(nameErr);
		}

		const updateInput: Types.StudentEntityInput = {
			id: input.id,
			name: input.name ?? existingStudent.name,
			email:
				input.email === null
					? null
					: (input.email?.value ?? existingStudent.email),
			phoneNumber:
				input.phoneNumber === null
					? null
					: (input.phoneNumber?.number ?? existingStudent.phoneNumber),
			dateOfBirth:
				input.dateOfBirth === null
					? null
					: (input.dateOfBirth ?? existingStudent.dateOfBirth),
			gender:
				input.gender === null ? null : (input.gender ?? existingStudent.gender),
			nationality:
				input.nationality === null
					? null
					: (input.nationality ?? existingStudent.nationality),
			createdAt: existingStudent.createdAt,
			updatedAt: new Date(),
		};

		try {
			const [updatedStudent] = await db
				.update(students)
				.set(updateInput)
				.where(eq(students.id, input.id))
				.returning();

			return updatedStudent;
		} catch {
			throw new Error(`Failed to update student with ID ${input.id}.`);
		}
	};

	export const fetchWithFilters = async (
		paginationArgs: Types.PaginationArgs | null,
		filters?: Types.StudentFilterArgs | null,
		orderBy?: Types.StudentsOrderByClause[] | null,
	): Promise<Types.StudentsWithFiltersResponse> => {
		const baseQuery = db
			.select({
				student: students,
				total: sql<number>`cast(count(*) over() as int)`,
			})
			.from(students)
			.$dynamic();

		return await _processStudentQuery(
			baseQuery,
			paginationArgs,
			orderBy,
			filters,
		);
	};
}

