import SchemaBuilder from "@pothos/core";
import AddGraphQL from "@pothos/plugin-add-graphql";
import DataloaderPlugin from "@pothos/plugin-dataloader";
import DrizzlePlugin from "@pothos/plugin-drizzle";
import ErrorsPlugin from "@pothos/plugin-errors";
import ScopeAuthPlugin from "@pothos/plugin-scope-auth";
import SimpleObjectsPlugin from "@pothos/plugin-simple-objects";
import TracingPlugin, {
	isRootField,
	wrapResolver,
} from "@pothos/plugin-tracing";
import WithInputPlugin from "@pothos/plugin-with-input";
import { getTableConfig } from "drizzle-orm/pg-core";
import { type DrizzleRelations, db, relations } from "@/backend/db/drizzleDb";
import logger from "@/backend/lib/logger";
import type { Email, PhoneNumber } from "../lib";
import type { AuthContexts, BaseContext } from "./gqlContext";

export interface PothosTypes {
	DrizzleRelations: DrizzleRelations;
	Context: BaseContext;
	AuthScopes: {
		loggedIn: boolean;
		admin: boolean;
		role: string;
	};
	AuthContexts: AuthContexts;
	Scalars: {
		DateTime: { Input: Date; Output: Date | string };
		Date: { Input: Date; Output: Date };
		JSON: { Input: unknown; Output: unknown };
		StringMap: {
			Input: Record<string, string>;
			Output: Record<string, string>;
		};
		// use following scalars for input types only for automatic validation
		PhoneNumber: { Input: PhoneNumber; Output: PhoneNumber };
		Email: { Input: Email; Output: Email };
	};
}

export const gqlSchemaBuilder = new SchemaBuilder<PothosTypes>({
	plugins: [
		DrizzlePlugin,
		AddGraphQL,
		ErrorsPlugin,
		ScopeAuthPlugin,
		WithInputPlugin,
		SimpleObjectsPlugin,
		DataloaderPlugin,
		TracingPlugin,
	],
	drizzle: {
		client: () => db,
		getTableConfig,
		relations,
	},
	scopeAuth: {
		authScopes: (ctx) => ({
			loggedIn: !!ctx.user,
			admin: !!ctx.roles.includes("admin"),
			role: (role: string) => ctx.roles.includes(role),
		}),
	},
	errors: {
		defaultTypes: [],
		onResolvedError: (error) => {
			logger.error("Handled error:", error);
		},
	},
	tracing: {
		// Enable tracing for rootFields by default, other fields need to opt in
		default: (config) => isRootField(config),
		// Log resolver execution duration
		wrap: (resolver, _options, config) =>
			wrapResolver(resolver, (_error, duration) => {
				logger.log(
					`Executed resolver ${config.parentType}.${config.name} in ${duration}ms`,
				);
			}),
	},
});

import { randomUUID } from "crypto";
import { GraphQLError } from "graphql";
import { SessionRepository, UserRepository } from "@/backend/db/repo";
import {
	generateAccessToken,
	generateRefreshToken,
	verifyToken,
} from "@/backend/lib";
import { comparePassword } from "@/backend/lib/auth/password";
import logger from "@/backend/lib/logger";
import type { SessionEntity, UserEntity } from "@/backend/types";
import { gqlSchemaBuilder } from "../gqlSchemaBuilder";
import {
	LoginInputPothosObject,
	LoginResponsePothosObject,
	RefreshTokenResponsePothosObject,
} from "../pothos";

gqlSchemaBuilder.mutationFields((t) => ({
	login: t.field({
		type: LoginResponsePothosObject,
		args: {
			input: t.arg({ type: LoginInputPothosObject, required: true }),
		},
		resolve: async (_parent, args, ctx) => {
			const { email, password } = args.input;

			let user: UserEntity | null;
			try {
				user = (await UserRepository.findByEmail(email.value)) ?? null;
			} catch (err) {
				logger.error(err);
				return null;
			}

			if (!user) {
				throw new GraphQLError("Invalid email or password", {
					extensions: { code: "INVALID_CREDENTIALS" },
				});
			}

			// Verify password
			const isPasswordValid = await comparePassword(password, user.password);

			if (!isPasswordValid) {
				throw new GraphQLError("Invalid email or password", {
					extensions: { code: "INVALID_CREDENTIALS" },
				});
			}

			// Generate tokens
			const accessToken = await generateAccessToken(user.id, user.email);
			const refreshToken = await generateRefreshToken(user.id, user.email);

			// Create session in database
			const sessionId = randomUUID();
			await SessionRepository.create({
				id: sessionId,
				userId: user.id,
				payload: JSON.stringify({
					createdAt: new Date().toISOString(),
					// Store session metadata only, not sensitive tokens
				}),
				lastActivity: Math.floor(Date.now() / 1000),
			});

			// Set httpOnly cookies for session and refresh token
			if (ctx.cookies) {
				ctx.cookies.set("session_id", sessionId, {
					httpOnly: true,
					secure: process.env.NODE_ENV === "production",
					sameSite: "lax",
					maxAge: 60 * 60 * 24 * 7, // 7 days
					path: "/",
				});

				ctx.cookies.set("refresh_token", refreshToken, {
					httpOnly: true,
					secure: process.env.NODE_ENV === "production",
					sameSite: "lax",
					maxAge: 60 * 60 * 24 * 7, // 7 days
					path: "/",
				});
			}

			return {
				token: accessToken,
				user,
			};
		},
	}),

	refreshToken: t.field({
		type: RefreshTokenResponsePothosObject,
		resolve: async (_parent, _args, ctx) => {
			// Try to get session ID from context (from cookie)
			const sessionId = ctx.sessionId;
			const refreshToken = ctx.refreshToken;

			if (!sessionId && !refreshToken) {
				throw new GraphQLError("No authentication session found", {
					extensions: { code: "UNAUTHENTICATED" },
				});
			}

			let session: SessionEntity | null = null;
			let user: UserEntity | null = null;

			// First try to validate using session ID (cookie-based)
			if (sessionId) {
				session = await SessionRepository.validate(sessionId);

				if (session?.userId) {
					const foundUser = await UserRepository.findById(session.userId);
					user = foundUser || null;

					if (!user) {
						logger.warn("[RefreshToken] Session found but user not found", {
							userId: session.userId,
						});
					}
				}
			}

			// If session validation failed, try refresh token
			if (!user && refreshToken) {
				const payload = await verifyToken(refreshToken);

				if (payload && payload.type === "refresh") {
					const foundUser = await UserRepository.findById(payload.userId);
					user = foundUser || null;

					if (user) {
						const foundSession = await SessionRepository.findByUserId(user.id);
						session = foundSession || null;

						if (!session) {
							logger.warn("[RefreshToken] User found but no session exists", {
								userId: user.id,
							});
						}
					}
				}
			}

			if (!user || !session) {
				throw new GraphQLError("Invalid session or refresh token", {
					extensions: { code: "INVALID_TOKEN" },
				});
			}

			// Generate new tokens (token rotation for security)
			const newAccessToken = await generateAccessToken(user.id, user.email);
			const newRefreshToken = await generateRefreshToken(user.id, user.email);

			// Update session activity
			await SessionRepository.update({
				...session,
				lastActivity: Math.floor(Date.now() / 1000),
			});

			// Refresh the cookies with new refresh token (token rotation)
			if (ctx.cookies && session.id) {
				ctx.cookies.set("session_id", session.id, {
					httpOnly: true,
					secure: process.env.NODE_ENV === "production",
					sameSite: "lax",
					maxAge: 60 * 60 * 24 * 7, // 7 days
					path: "/",
				});

				// Rotate refresh token for enhanced security
				ctx.cookies.set("refresh_token", newRefreshToken, {
					httpOnly: true,
					secure: process.env.NODE_ENV === "production",
					sameSite: "lax",
					maxAge: 60 * 60 * 24 * 7, // 7 days
					path: "/",
				});
			}

			return {
				token: newAccessToken,
				user,
			};
		},
	}),

	logout: t.field({
		type: "Boolean",
		authScopes: {
			loggedIn: true,
		},
		resolve: async (_parent, _args, ctx) => {
			if (!ctx.user) {
				return false;
			}

			// Delete all sessions for the user
			await SessionRepository.deleteByUserId(ctx.user.id);

			// Clear authentication cookies
			if (ctx.cookies) {
				ctx.cookies.delete("session_id");
				ctx.cookies.delete("refresh_token");
			}

			return true;
		},
	}),
}));

