import { type JWTPayload as JoseJWTPayload, jwtVerify, SignJWT } from "jose";

// Validate JWT_SECRET is set in production
if (process.env.NODE_ENV === "production" && !process.env.JWT_SECRET) {
	throw new Error("JWT_SECRET must be set in production environment");
}

const JWT_SECRET =
	process.env.JWT_SECRET ?? "your-secret-key-change-this-in-production";
const JWT_ACCESS_TOKEN_EXPIRY = "15m"; // 15 minutes
const JWT_REFRESH_TOKEN_EXPIRY = "7d"; // 7 days

const secret = new TextEncoder().encode(JWT_SECRET);

export interface CustomJWTPayload extends JoseJWTPayload {
	userId: number;
	email: string;
	type: "access" | "refresh";
}

/**
 * Generate an access token for a user
 */
export async function generateAccessToken(
	userId: number,
	email: string,
): Promise<string> {
	const token = await new SignJWT({
		userId,
		email,
		type: "access" as const,
	})
		.setProtectedHeader({ alg: "HS256" })
		.setIssuedAt()
		.setExpirationTime(JWT_ACCESS_TOKEN_EXPIRY)
		.sign(secret);

	return token;
}

/**
 * Generate a refresh token for a user
 */
export async function generateRefreshToken(
	userId: number,
	email: string,
): Promise<string> {
	const token = await new SignJWT({
		userId,
		email,
		type: "refresh" as const,
	})
		.setProtectedHeader({ alg: "HS256" })
		.setIssuedAt()
		.setExpirationTime(JWT_REFRESH_TOKEN_EXPIRY)
		.sign(secret);

	return token;
}

/**
 * Verify and decode a JWT token
 */
export async function verifyToken(
	token: string,
): Promise<CustomJWTPayload | null> {
	try {
		const { payload } = await jwtVerify(token, secret);
		return payload as unknown as CustomJWTPayload;
	} catch {
		// Token verification failed - invalid or expired
		return null;
	}
}

/**
 * Extract token from Authorization header
 */
export function extractTokenFromHeader(
	authHeader: string | null,
): string | null {
	if (!authHeader?.startsWith("Bearer ")) {
		return null;
	}
	return authHeader.substring(7);
}

import logger from "@/backend/lib/logger";

/**
 * Environment variable validation
 * Ensures critical environment variables are properly configured
 */

export interface EnvironmentConfig {
	nodeEnv: string;
	jwtSecret: string;
	databaseUrl: string;
	cacheProvider: "redis" | "postgres";
	redisProvider: "local" | "upstash";
	redisUrl: string;
	upstashRedisUrl?: string;
	upstashRedisToken?: string;
	allowedOrigin: string | undefined;
}

/**
 * Validate JWT_SECRET
 * In production, must be at least 32 characters for security
 */
function validateJwtSecret(): string {
	const jwtSecret = process.env.JWT_SECRET;

	if (!jwtSecret) {
		if (process.env.NODE_ENV === "production") {
			throw new Error(
				"CRITICAL: JWT_SECRET is not set in production environment. " +
					"This is required for secure authentication.",
			);
		} else {
			// Use a default in development (not recommended for production)
			logger.warn(
				"⚠️  JWT_SECRET not set. Using default for development. " +
					"DO NOT use this in production!",
			);
			return "development-secret-change-me-in-production";
		}
	}

	if (process.env.NODE_ENV === "production" && jwtSecret.length < 32) {
		throw new Error(
			"CRITICAL: JWT_SECRET must be at least 32 characters in production. " +
				`Current length: ${jwtSecret.length}`,
		);
	}

	return jwtSecret;
}

/**
 * Validate DATABASE_URL
 */
function validateDatabaseUrl(): string {
	const databaseUrl = process.env.DATABASE_URL;

	if (!databaseUrl) {
		if (process.env.NODE_ENV === "production") {
			throw new Error(
				"CRITICAL: DATABASE_URL is not set in production environment.",
			);
		} else {
			logger.warn("⚠️  DATABASE_URL not set. Database operations may fail.");
			return "";
		}
	}

	// Basic validation for PostgreSQL URL format
	if (
		!databaseUrl.startsWith("postgresql://") &&
		!databaseUrl.startsWith("postgres://")
	) {
		logger.warn(
			"⚠️  DATABASE_URL may not be a valid PostgreSQL connection string.",
		);
	}

	return databaseUrl;
}

/**
 * Validate CACHE_PROVIDER
 */
function validateCacheProvider(): "redis" | "postgres" {
	const provider = process.env.CACHE_PROVIDER?.toLowerCase() as
		| "redis"
		| "postgres"
		| undefined;

	if (!provider) {
		// Default to redis for development
		return "redis";
	}

	if (provider !== "redis" && provider !== "postgres") {
		logger.warn(
			`⚠️  Invalid CACHE_PROVIDER: ${provider}. Must be 'redis' or 'postgres'. Using 'redis'.`,
		);
		return "redis";
	}

	return provider;
}

/**
 * Validate REDIS_PROVIDER
 */
function validateRedisProvider(): "local" | "upstash" {
	const provider = process.env.REDIS_PROVIDER?.toLowerCase() as
		| "local"
		| "upstash"
		| undefined;

	if (!provider) {
		// Default to local for development
		return "local";
	}

	if (provider !== "local" && provider !== "upstash") {
		logger.warn(
			`⚠️  Invalid REDIS_PROVIDER: ${provider}. Must be 'local' or 'upstash'. Using 'local'.`,
		);
		return "local";
	}

	return provider;
}

/**
 * Validate Redis configuration based on provider
 */
function validateRedisConfig(): {
	redisProvider: "local" | "upstash";
	redisUrl: string;
	upstashRedisUrl?: string;
	upstashRedisToken?: string;
} {
	const provider = validateRedisProvider();

	if (provider === "local") {
		const redisUrl = process.env.REDIS_URL || "redis://localhost:6379";
		logger.log(`Redis provider: local (${redisUrl})`);
		return { redisProvider: provider, redisUrl };
	}

	// Upstash provider
	const upstashRedisUrl = process.env.UPSTASH_REDIS_REST_URL;
	const upstashRedisToken = process.env.UPSTASH_REDIS_REST_TOKEN;

	if (!upstashRedisUrl || !upstashRedisToken) {
		if (process.env.NODE_ENV === "production") {
			throw new Error(
				"CRITICAL: Upstash Redis provider requires UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN. " +
					"Get these from https://console.upstash.com/",
			);
		} else {
			logger.warn(
				"⚠️  Upstash Redis selected but credentials missing. Falling back to local Redis.",
			);
			return {
				redisProvider: "local",
				redisUrl: process.env.REDIS_URL || "redis://localhost:6379",
			};
		}
	}

	logger.log("Redis provider: upstash (serverless)");
	return {
		redisProvider: "upstash",
		redisUrl: "",
		upstashRedisUrl,
		upstashRedisToken,
	};
}

/**
 * Validate ALLOWED_ORIGIN for CORS
 */
function validateAllowedOrigin(): string | undefined {
	const allowedOrigin = process.env.ALLOWED_ORIGIN;

	if (process.env.NODE_ENV === "production" && !allowedOrigin) {
		logger.warn(
			"⚠️  ALLOWED_ORIGIN not set in production. " +
				"CORS will use default. Set this for security.",
		);
	}

	return allowedOrigin;
}

/**
 * Main validation function
 * Call this early in application startup
 */
export function validateEnvironment(): EnvironmentConfig {
	const nodeEnv = process.env.NODE_ENV || "development";

	logger.log("🔍 Validating environment variables...");
	logger.log(`Environment: ${nodeEnv}`);

	try {
		const cacheProvider = validateCacheProvider();
		const redisConfig =
			cacheProvider === "redis"
				? validateRedisConfig()
				: {
						redisProvider: "local" as const,
						redisUrl: process.env.REDIS_URL || "redis://localhost:6379",
					};

		const config: EnvironmentConfig = {
			nodeEnv,
			jwtSecret: validateJwtSecret(),
			databaseUrl: validateDatabaseUrl(),
			cacheProvider,
			...redisConfig,
			allowedOrigin: validateAllowedOrigin(),
		};

		logger.log("✅ Environment validation successful!");

		// Log configuration (without sensitive data)
		if (nodeEnv === "development") {
			logger.log("Configuration:");
			logger.log(`  NODE_ENV: ${config.nodeEnv}`);
			logger.log(`  JWT_SECRET: ${config.jwtSecret ? "[SET]" : "[NOT SET]"}`);
			logger.log(
				`  DATABASE_URL: ${config.databaseUrl ? "[SET]" : "[NOT SET]"}`,
			);
			logger.log(`  CACHE_PROVIDER: ${config.cacheProvider}`);
			logger.log(`  REDIS_PROVIDER: ${config.redisProvider}`);
			if (config.redisProvider === "local") {
				logger.log(`  REDIS_URL: ${config.redisUrl}`);
			} else {
				logger.log(
					`  UPSTASH_REDIS_REST_URL: ${config.upstashRedisUrl ? "[SET]" : "[NOT SET]"}`,
				);
				logger.log(
					`  UPSTASH_REDIS_REST_TOKEN: ${config.upstashRedisToken ? "[SET]" : "[NOT SET]"}`,
				);
			}
			logger.log(`  ALLOWED_ORIGIN: ${config.allowedOrigin || "[DEFAULT]"}`);
		}

		return config;
	} catch (error) {
		logger.error("❌ Environment validation failed!");
		logger.error(error instanceof Error ? error.message : String(error));

		// Exit in production to prevent insecure startup
		if (nodeEnv === "production") {
			logger.error("Exiting due to invalid environment configuration.");
			process.exit(1);
		}

		throw error;
	}
}

/**
 * Optional: Validate specific environment variables at runtime
 */
export function requireEnv(name: string): string {
	const value = process.env[name];

	if (!value) {
		throw new Error(`Required environment variable ${name} is not set`);
	}

	return value;
}

/**
 * Optional: Get environment variable with default
 */
export function getEnv(name: string, defaultValue: string): string {
	return process.env[name] || defaultValue;
}

// Auto-validate on module import (runs once at startup)
// Comment this out if you want manual validation
if (typeof window === "undefined") {
	// Only run on server-side
	validateEnvironment();
}

import logger from "@/backend/lib/logger";
import { cacheService } from "@/backend/services/cache";

/**
 * Rate limiting configuration for API endpoints
 * Uses cache service (Redis or PostgreSQL) for distributed rate limiting across multiple instances
 * Implements sliding window algorithm for accurate rate limiting
 */

/**
 * Rate Limiter Class
 * Custom implementation using our cache service interface
 */
class RateLimiter {
	private prefix: string;
	private maxRequests: number;
	private windowMs: number;

	constructor(prefix: string, maxRequests: number, windowMs: number) {
		this.prefix = prefix;
		this.maxRequests = maxRequests;
		this.windowMs = windowMs;
	}

	/**
	 * Check if request is allowed for given identifier
	 * Returns remaining requests and reset time
	 */
	async limit(identifier: string): Promise<{
		success: boolean;
		limit: number;
		remaining: number;
		reset: number;
	}> {
		const key = `${this.prefix}:${identifier}`;
		const now = Date.now();
		const windowStart = now - this.windowMs;

		try {
			// Use Redis sorted set for sliding window
			// Score is timestamp, member is unique request ID
			const requestId = `${now}:${Math.random()}`;

			// Remove old entries outside the window
			await cacheService.pipeline([
				{ command: "zremrangebyscore", args: [key, 0, windowStart] },
				{ command: "zadd", args: [key, now, requestId] },
				{ command: "zcard", args: [key] },
				{ command: "expire", args: [key, Math.ceil(this.windowMs / 1000)] },
			]);

			// Count requests in current window
			const count = await this.getCount(key);
			const remaining = Math.max(0, this.maxRequests - count);
			const reset = now + this.windowMs;

			return {
				success: count <= this.maxRequests,
				limit: this.maxRequests,
				remaining,
				reset,
			};
		} catch (error) {
			logger.error("Rate limiting error:", error);
			// Fail open - allow request if cache has issues
			return {
				success: true,
				limit: this.maxRequests,
				remaining: this.maxRequests,
				reset: now + this.windowMs,
			};
		}
	}

	/**
	 * Get current request count for a key
	 */
	private async getCount(key: string): Promise<number> {
		try {
			const value = await cacheService.get(key);
			if (!value) return 0;

			// For sorted set implementation, we need to count members
			// For now, use simple counter
			return Number.parseInt(value, 10) || 0;
		} catch {
			return 0;
		}
	}

	/**
	 * Simple counter-based rate limiting (fallback)
	 */
	async limitSimple(identifier: string): Promise<{
		success: boolean;
		limit: number;
		remaining: number;
		reset: number;
	}> {
		const key = `${this.prefix}:${identifier}`;
		const now = Date.now();
		const ttlSeconds = Math.ceil(this.windowMs / 1000);

		try {
			const current = await cacheService.get(key);
			const count = current ? Number.parseInt(current, 10) : 0;

			if (count === 0) {
				// First request in window
				await cacheService.set(key, "1", { ex: ttlSeconds });
				return {
					success: true,
					limit: this.maxRequests,
					remaining: this.maxRequests - 1,
					reset: now + this.windowMs,
				};
			}

			if (count >= this.maxRequests) {
				// Limit exceeded
				const ttl = await cacheService.ttl(key);
				return {
					success: false,
					limit: this.maxRequests,
					remaining: 0,
					reset: now + ttl * 1000,
				};
			}

			// Increment counter
			await cacheService.incr(key);
			const ttl = await cacheService.ttl(key);

			return {
				success: true,
				limit: this.maxRequests,
				remaining: this.maxRequests - (count + 1),
				reset: now + ttl * 1000,
			};
		} catch (error) {
			logger.error("Rate limiting error:", error);
			// Fail open - allow request if cache has issues
			return {
				success: true,
				limit: this.maxRequests,
				remaining: this.maxRequests,
				reset: now + this.windowMs,
			};
		}
	}
}

/**
 * GraphQL API rate limiter
 * Allows 100 requests per minute per IP address
 */
export const graphqlRateLimiter = new RateLimiter(
	"ratelimit:graphql",
	100,
	60 * 1000, // 1 minute
);

/**
 * Authentication endpoints rate limiter (more restrictive)
 * Allows 10 login attempts per 15 minutes per IP address
 * Prevents brute force attacks
 */
export const authRateLimiter = new RateLimiter(
	"ratelimit:auth",
	10,
	15 * 60 * 1000, // 15 minutes
);

/**
 * General API rate limiter
 * Allows 200 requests per minute per IP address
 */
export const apiRateLimiter = new RateLimiter(
	"ratelimit:api",
	200,
	60 * 1000, // 1 minute
);

/**
 * Helper function to check rate limit and return appropriate response
 */
export async function checkRateLimit(
	identifier: string,
	limiter: RateLimiter = graphqlRateLimiter,
): Promise<{
	success: boolean;
	limit: number;
	remaining: number;
	reset: number;
}> {
	const isDev = process.env.NODE_ENV === "development";
	try {
		const { success, limit, remaining, reset } =
			await limiter.limitSimple(identifier);
		if (isDev) {
			if (!success) {
				logger.warn(
					`Rate limit would have been exceeded for identifier: ${identifier} (development mode, not enforced)`,
				);
			}
			// Always allow in development
			return { success: true, limit, remaining, reset };
		} else {
			if (!success) {
				logger.warn(`Rate limit exceeded for identifier: ${identifier}`);
			}
			return { success, limit, remaining, reset };
		}
	} catch (error) {
		// If rate limiting fails (e.g., cache is down), allow the request
		// but log the error for monitoring
		logger.error("Rate limiting error:", error);
		return { success: true, limit: 0, remaining: 0, reset: 0 };
	}
}

/**
 * Extract client identifier from request
 * Uses IP address, with fallback to a default identifier
 */
export function getClientIdentifier(request: Request): string {
	// Try to get IP from various headers (for proxies/load balancers)
	const forwardedFor = request.headers.get("x-forwarded-for");
	const realIp = request.headers.get("x-real-ip");
	const cfConnectingIp = request.headers.get("cf-connecting-ip"); // Cloudflare

	// Use the first available IP
	const ip =
		cfConnectingIp || realIp || forwardedFor?.split(",")[0] || "unknown";

	return ip.trim();
}

function getNextDevServerUrl(): string {
	const envUrl = process.env.NEXT_PUBLIC_BASE_URL;
	if (process.env.NODE_ENV === "production" && !envUrl) {
		throw new Error("NEXT_PUBLIC_BASE_URL must be set in production mode");
	}

	const url = envUrl ?? "http://localhost:3000";

	// Validate URL format
	try {
		const parsedUrl = new URL(url);

		// Ensure protocol is http or https
		if (!parsedUrl.protocol.match(/^https?:$/)) {
			throw new Error(
				`Invalid protocol in NEXT_PUBLIC_BASE_URL: ${parsedUrl.protocol}. Must be http: or https:`,
			);
		}

		// Validate hostname is present
		if (!parsedUrl.hostname) {
			throw new Error("NEXT_PUBLIC_BASE_URL must include a valid hostname");
		}

		// Return the URL without trailing slashes (port is preserved by URL constructor)
		return `${parsedUrl.protocol}//${parsedUrl.host}${parsedUrl.pathname.replace(/\/+$/, "")}`;
	} catch (error) {
		if (error instanceof TypeError) {
			throw new Error(
				`Invalid NEXT_PUBLIC_BASE_URL format: ${url}. Must be a valid URL (e.g., http://localhost:3000 or https://domain.com:8080)`,
			);
		}
		throw error;
	}
}

export const NEXT_PUBLIC_BASE_URL = getNextDevServerUrl();

export function getGraphQLEndpoint(): string {
	const GRAPHQL_PATH = "/api/graphql";
	const graphqlEndpoint = `${NEXT_PUBLIC_BASE_URL.replace(/\/+$/, "")}${GRAPHQL_PATH}`;
	return graphqlEndpoint;
}

export const GRAPHQL_ENDPOINT = getGraphQLEndpoint();

import logger from "@/backend/lib/logger";
import type { CacheProvider, ICacheService } from "./ICacheService";
import { PostgresCacheAdapter } from "./PostgresCacheAdapter";

// Module-level state replaces the static class properties
let instance: ICacheService | null = null;
let initializationPromise: Promise<ICacheService> | null = null;

/**
 * Get cache provider from environment variable
 */
function getCacheProvider(): CacheProvider {
	const provider = (
		process.env.CACHE_PROVIDER || "redis"
	).toLowerCase() as CacheProvider;

	if (provider !== "redis" && provider !== "postgres") {
		logger.warn(
			`⚠️  Invalid CACHE_PROVIDER: ${provider}. Must be 'redis' or 'postgres'. Using 'redis'.`,
		);
		return "redis";
	}

	return provider;
}

/**
 * Create PostgreSQL cache adapter
 */
function createPostgresCache(): ICacheService {
	logger.log("Connecting to PostgreSQL cache (UNLOGGED table)");
	return new PostgresCacheAdapter();
}

/**
 * Create Redis cache adapter (lazy import to avoid loading Redis when using PostgreSQL)
 */
async function createRedisCache(): Promise<ICacheService> {
	logger.log("Connecting to Redis cache");
	// Use dynamic import to avoid importing Redis module when using PostgreSQL
	const { RedisCacheAdapter } = await import("./RedisCacheAdapter");
	return new RedisCacheAdapter();
}

/**
 * Create cache service based on provider type
 */
async function createCacheService(): Promise<ICacheService> {
	const provider = getCacheProvider();

	logger.log(`🔧 Initializing Cache with provider: ${provider}`);

	switch (provider) {
		case "postgres":
			return createPostgresCache();

		case "redis":
			return await createRedisCache();

		default:
			logger.warn(`Unknown cache provider: ${provider}, falling back to redis`);
			return await createRedisCache();
	}
}

/**
 * Get cache service instance (singleton)
 */
export const getCacheService = async (): Promise<ICacheService> => {
	// If already fully initialized, return the instance immediately
	if (instance) {
		return instance;
	}

	// Cache the initialization promise to prevent race conditions
	// causing multiple connections during startup
	if (!initializationPromise) {
		initializationPromise = (async () => {
			try {
				const service = await createCacheService();
				instance = service;
				return instance;
			} catch (error) {
				initializationPromise = null;
				logger.error("Failed to initialize cache service", error);
				throw error;
			}
		})();
	}

	return initializationPromise;
};

/**
 * Reset instance (useful for testing)
 */
export const resetCacheService = (): void => {
	if (instance) {
		void instance.disconnect();
		instance = null;
	}
	initializationPromise = null;
};

/**
 * Health check for cache connection
 */
export const checkCacheHealth = async (): Promise<boolean> => {
	try {
		const cache = await getCacheService();
		return await cache.ping();
	} catch (error) {
		logger.error("Cache health check failed:", error);
		return false;
	}
};

/**
 * Export singleton cache service instance
 * This provides a direct instance for synchronous usage where methods
 * will automatically wait for the underlying service to initialize.
 */
export const cacheService = {
	get: async (key: string) => {
		const service = await getCacheService();
		return service.get(key);
	},
	set: async (
		key: string,
		value: string,
		options?: { ex?: number; px?: number },
	) => {
		const service = await getCacheService();
		return service.set(key, value, options);
	},
	del: async (key: string) => {
		const service = await getCacheService();
		return service.del(key);
	},
	expire: async (key: string, seconds: number) => {
		const service = await getCacheService();
		return service.expire(key, seconds);
	},
	ttl: async (key: string) => {
		const service = await getCacheService();
		return service.ttl(key);
	},
	incr: async (key: string) => {
		const service = await getCacheService();
		return service.incr(key);
	},
	pipeline: async (
		commands: Array<{ command: string; args: (string | number)[] }>,
	) => {
		const service = await getCacheService();
		return service.pipeline(commands);
	},
	ping: async () => {
		const service = await getCacheService();
		return service.ping();
	},
	disconnect: async () => {
		const service = await getCacheService();
		return service.disconnect();
	},
};

import { db } from "@/backend/db/drizzleDb";
import { CacheDbRepository } from "@/backend/db/repo/cache.repository";
import logger from "@/backend/lib/logger";
import type { ICacheService } from "./ICacheService";

/**
 * PostgreSQL Cache Adapter
 * Implements ICacheService using PostgreSQL with UNLOGGED tables
 * Uses Drizzle ORM for database operations
 */
export class PostgresCacheAdapter implements ICacheService {
	private cleanupInterval: NodeJS.Timeout | null = null;

	constructor() {
		// Start periodic cleanup of expired entries
		this.startCleanup();
	}

	/**
	 * Get a value from cache
	 */
	async get(key: string): Promise<string | null> {
		try {
			const entry = await CacheDbRepository.get(key);
			return entry?.value || null;
		} catch (error) {
			logger.error("Postgres cache get error:", error);
			return null;
		}
	}

	/**
	 * Set a value in cache
	 */
	async set(
		key: string,
		value: string,
		options?: { ex?: number; px?: number },
	): Promise<void> {
		try {
			const ttlSeconds =
				options?.ex || options?.px
					? options.ex || (options.px ?? 0) / 1000
					: 3600; // Default 1 hour
			const expiresAt = new Date(Date.now() + ttlSeconds * 1000);

			await CacheDbRepository.set(key, value, expiresAt);
		} catch (error) {
			logger.error("Postgres cache set error:", error);
			throw error;
		}
	}

	/**
	 * Increment a value in cache
	 */
	async incr(key: string): Promise<number> {
		try {
			return await CacheDbRepository.incr(key);
		} catch (error) {
			logger.error("Postgres cache incr error:", error);
			throw error;
		}
	}

	/**
	 * Set expiration time on a key
	 */
	async expire(key: string, seconds: number): Promise<void> {
		try {
			const entry = await CacheDbRepository.get(key);
			if (!entry) {
				return; // Key doesn't exist
			}

			const expiresAt = new Date(Date.now() + seconds * 1000);
			await CacheDbRepository.set(key, entry.value, expiresAt);
		} catch (error) {
			logger.error("Postgres cache expire error:", error);
			throw error;
		}
	}

	/**
	 * Get time to live for a key
	 */
	async ttl(key: string): Promise<number> {
		try {
			return await CacheDbRepository.ttl(key);
		} catch (error) {
			logger.error("Postgres cache ttl error:", error);
			return -1;
		}
	}

	/**
	 * Delete a key
	 */
	async del(key: string): Promise<void> {
		try {
			await CacheDbRepository.del(key);
		} catch (error) {
			logger.error("Postgres cache del error:", error);
			throw error;
		}
	}

	/**
	 * Execute a pipeline of commands (for atomic operations)
	 * Uses database transactions for atomicity
	 */
	async pipeline(
		commands: Array<{ command: string; args: (string | number)[] }>,
	): Promise<unknown[]> {
		try {
			return await db.transaction(async () => {
				const results: unknown[] = [];

				for (const cmd of commands) {
					switch (cmd.command) {
						case "zremrangebyscore":
							// For rate limiting: remove old entries
							// This is a no-op for PostgreSQL cache as we handle expiration differently
							results.push(0);
							break;

						case "zadd": {
							// For rate limiting: add new entry
							const [key, score, member] = cmd.args as [string, number, string];
							const expiresAt = new Date(score + 3600000); // 1 hour from score
							await CacheDbRepository.set(key, member, expiresAt);
							results.push(1);
							break;
						}

						case "zcard": {
							// For rate limiting: count entries
							const entry = await CacheDbRepository.get(cmd.args[0] as string);
							results.push(entry ? 1 : 0);
							break;
						}

						case "expire": {
							// Set expiration
							const [expKey, expSeconds] = cmd.args as [string, number];
							await this.expire(expKey, expSeconds);
							results.push(1);
							break;
						}

						default:
							logger.warn(`Unsupported pipeline command: ${cmd.command}`);
							results.push(null);
					}
				}

				return results;
			});
		} catch (error) {
			logger.error("Postgres cache pipeline error:", error);
			throw error;
		}
	}

	/**
	 * Check if cache connection is healthy
	 */
	async ping(): Promise<boolean> {
		try {
			return await CacheDbRepository.ping();
		} catch (error) {
			logger.error("Postgres cache ping error:", error);
			return false;
		}
	}

	/**
	 * Close the connection
	 */
	async disconnect(): Promise<void> {
		try {
			if (this.cleanupInterval) {
				clearInterval(this.cleanupInterval);
				this.cleanupInterval = null;
			}
			logger.log("Postgres cache adapter disconnected");
		} catch (error) {
			logger.error("Postgres cache disconnect error:", error);
		}
	}

	/**
	 * Start periodic cleanup of expired entries
	 */
	private startCleanup(): void {
		// Run cleanup every 5 minutes
		this.cleanupInterval = setInterval(
			async () => {
				try {
					await CacheDbRepository.deleteExpired();
				} catch (error) {
					logger.error("Cache cleanup error:", error);
				}
			},
			5 * 60 * 1000,
		);
	}
}

import Redis from "ioredis";
import logger from "@/backend/lib/logger";
import type { IRedisService } from "./IRedisService";

/**
 * Local Redis Adapter
 * Uses ioredis to connect to a local or self-hosted Redis instance
 * Perfect for development and self-hosted production environments
 */
export class LocalRedisAdapter implements IRedisService {
	private client: Redis;

	constructor(url: string = "redis://localhost:6379") {
		this.client = new Redis(url, {
			maxRetriesPerRequest: 3,
			retryStrategy: (times: number) => {
				const delay = Math.min(times * 50, 2000);
				logger.warn(
					`Redis connection retry attempt ${times}, waiting ${delay}ms`,
				);
				return delay;
			},
			reconnectOnError: (err: Error) => {
				logger.error("Redis connection error:", err.message);
				return true;
			},
		});

		this.client.on("connect", () => {
			logger.log("✅ Connected to local Redis");
		});

		this.client.on("error", (err: Error) => {
			logger.error("❌ Redis error:", err.message);
		});

		this.client.on("ready", () => {
			logger.log("🚀 Redis is ready");
		});
	}

	async get(key: string): Promise<string | null> {
		return await this.client.get(key);
	}

	async set(
		key: string,
		value: string,
		options?: { ex?: number; px?: number },
	): Promise<void> {
		if (options?.ex) {
			await this.client.set(key, value, "EX", options.ex);
		} else if (options?.px) {
			await this.client.set(key, value, "PX", options.px);
		} else {
			await this.client.set(key, value);
		}
	}

	async incr(key: string): Promise<number> {
		return await this.client.incr(key);
	}

	async expire(key: string, seconds: number): Promise<void> {
		await this.client.expire(key, seconds);
	}

	async ttl(key: string): Promise<number> {
		return await this.client.ttl(key);
	}

	async del(key: string): Promise<void> {
		await this.client.del(key);
	}

	async pipeline(
		commands: Array<{ command: string; args: string[] | number[] }>,
	): Promise<unknown[]> {
		const pipeline = this.client.pipeline();

		for (const cmd of commands) {
			(pipeline as Record<string, (...args: (string | number)[]) => unknown>)[
				cmd.command
			](...cmd.args);
		}

		const results = await pipeline.exec();
		return (
			results?.map(([err, result]) => {
				if (err) throw err;
				return result;
			}) || []
		);
	}

	async ping(): Promise<boolean> {
		try {
			const result = await this.client.ping();
			return result === "PONG";
		} catch {
			return false;
		}
	}

	async disconnect(): Promise<void> {
		await this.client.quit();
		logger.log("Disconnected from Redis");
	}

	/**
	 * Get the native ioredis client for advanced operations
	 */
	getNativeClient(): Redis {
		return this.client;
	}
}

