import type { Bucket, GetFilesResponse, Storage } from "@google-cloud/storage";
import crypto from "crypto";
import { StorageDbRepository } from "@/backend/db/repo";
import logger from "@/backend/lib/logger";
import * as Types from "@/backend/types";
import { StorageUtils } from "@/backend/utils";
import { OrderSortDirection } from "@/lib/enum";
import { getGcpStorageClient } from "./gcp-auth";
import {
	STORAGE_CONFIG,
	type StorageService,
	StorageValidationError,
} from "./storage.service.interface";

type GcsApiResponse = {
	prefixes?: string[];
};

const bucketName = process.env.GCP_BUCKET_NAME;

export const gcpBaseUrl = `https://storage.googleapis.com/${bucketName}/`;

/**
 * Clean path for GCS - removes leading slashes and normalizes trailing slashes
 */
function cleanGcsPath(path: string, addTrailingSlash = false): string {
	if (!path || path.length === 0) {
		return "";
	}

	// Remove leading slashes and trailing slashes
	const cleaned = path.replace(/^\/+/, "").replace(/\/$/, "");

	// Add trailing slash if requested and path is not empty
	return addTrailingSlash && cleaned.length > 0 ? `${cleaned}/` : cleaned;
}

export async function createGcpStorage(): Promise<Storage> {
	const storage = await getGcpStorageClient();
	return storage;
}

class GcpAdapter implements StorageService {
	private readonly bucket: Bucket;

	constructor(storage: Storage) {
		if (!bucketName) {
			throw new Error("GCP_BUCKET_NAME environment variable is required");
		}
		this.bucket = storage.bucket(bucketName);
	}

	async fileExists(path: string): Promise<boolean> {
		try {
			const file = this.bucket.file(path);
			const [exists] = await file.exists();
			return exists;
		} catch (error) {
			logger.error(`Error checking file existence: ${path}`, error);
			return false;
		}
	}

	async prepareUpload(
		input: Types.UploadPreparationInput,
	): Promise<Types.UploadPreparationResult> {
		try {
			logger.info("Preparing upload", {
				path: input.path,
				fileSize: input.fileSize,
			});

			void StorageUtils.validateUpload(
				input.path,
				input.fileSize,
				input.contentType,
			).then((err) => {
				if (err) throw new StorageValidationError(err);
			});

			const file = this.bucket.file(input.path);

			const result = await file.getSignedUrl({
				version: "v4",
				expires: Date.now() + STORAGE_CONFIG.SIGNED_URL_DURATION * 60 * 1000,
				contentType: input.contentType,
				action: "write",
				contentMd5: input.contentMd5,
			});

			const signedUrl = result[0];

			// Generate a unique ID for tracking this upload
			const uploadId = crypto.randomUUID();

			logger.info("Prepared upload successfully", {
				uploadId,
				path: input.path,
				uploadType: Types.UploadType.SIGNED_URL,
			});

			return {
				id: uploadId,
				url: signedUrl,
				uploadType: Types.UploadType.SIGNED_URL,
			};
		} catch (error) {
			logger.error("Failed to prepare upload", {
				path: input.path,
				error: error instanceof Error ? error.message : String(error),
				stack: error instanceof Error ? error.stack : undefined,
			});
			throw error;
		}
	}

	async uploadFile(
		path: string,
		contentType: string,
		buffer: Buffer,
	): Promise<Types.FileUploadResult> {
		try {
			const fileSize = buffer.byteLength;

			const uploadErr = await StorageUtils.validateUpload(
				path,
				fileSize,
				contentType,
			);
			if (uploadErr) {
				return {
					success: false,
					message: uploadErr,
					data: null,
				};
			}

			// Check if the directory exists in DB and get permissions
			const directoryPath = path.substring(0, path.lastIndexOf("/"));

			// Check if the directory exists in DB and get permissions
			const dbDirectory =
				await StorageDbRepository.directoryByPath(directoryPath);

			if (dbDirectory) {
				// Directory exists in DB, check permissions
				if (!dbDirectory.allowUploads) {
					return {
						success: false,
						message: "Uploads not allowed in this directory",
						data: null,
					};
				}
			} else {
				// Directory not in DB, check if it exists in bucket (default permissions apply)
				let bucketDirExists = false;
				try {
					const folderBlob = `${directoryPath}/`;
					const file = this.bucket.file(folderBlob);
					const [exists] = await file.exists();
					bucketDirExists = exists;
				} catch {
					bucketDirExists = false;
				}

				if (!bucketDirExists && directoryPath.length > 0) {
					return {
						success: false,
						message: "Directory does not exist",
						data: null,
					};
				}
			}

			const file = this.bucket.file(path);
			await file.save(buffer, {
				contentType: contentType,
			});

			// Create file entity in database
			const fileEntity = await StorageDbRepository.createFile(path, false);

			const [metadata] = await file.getMetadata();
			const bucketFile = StorageUtils.blobToFileInfo(metadata, gcpBaseUrl);
			const fileInfo = StorageUtils.combineFileData(bucketFile, fileEntity);

			return {
				success: true,
				message: "File uploaded successfully",
				data: fileInfo,
			};
		} catch (error) {
			logger.error(`Failed to upload file: ${path}`, error);
			return {
				success: false,
				message: `Failed to upload file: ${error instanceof Error ? error.message : String(error)}`,
				data: null,
			};
		}
	}

	async listFiles(
		input: Types.FilesListSearchInput,
	): Promise<Types.StorageObjectList> {
		// Clean the input path and add trailing slash for prefix
		const prefix = cleanGcsPath(input.path || "", true);
		const delimiter = "/";

		// Single API call to get both files and directories
		const response: GetFilesResponse = await this.bucket.getFiles({
			prefix,
			delimiter,
			autoPaginate: false,
		});

		const [files] = response;
		const apiResponse = response[2] as GcsApiResponse | undefined;

		const items: Array<Types.FileInfo | Types.DirectoryInfo> = [];

		// Collect all file paths for batch DB query
		const filePaths: string[] = [];
		const validFiles = files.filter((file) => file.name !== prefix); // Skip folder markers

		for (const file of validFiles) {
			filePaths.push(file.name);
		}

		// Collect all directory paths for batch DB query
		const dirPaths: string[] = [];
		if (apiResponse?.prefixes) {
			for (const dirPrefix of apiResponse.prefixes) {
				const dirPath = dirPrefix.replace(/\/$/, "");
				dirPaths.push(dirPath);
			}
		}

		// Batch database queries
		const [dbFiles, dbDirectories] = await Promise.all([
			filePaths.length > 0 ? StorageDbRepository.filesByPaths(filePaths) : [],
			dirPaths.length > 0
				? StorageDbRepository.directoriesByPaths(dirPaths)
				: [],
		]);

		// Create lookup maps for O(1) access
		const dbFileMap = new Map();
		dbFiles.forEach((dbFile) => {
			if (dbFile) {
				dbFileMap.set(dbFile.path, dbFile);
			}
		});

		const dbDirMap = new Map();
		dbDirectories.forEach((dbDir) => {
			if (dbDir) {
				dbDirMap.set(dbDir.path, dbDir);
			}
		});

		// Create folder file count map for efficient lookup
		const folderFileCountMap = new Map<string, number>();
		if (apiResponse?.prefixes) {
			// Count files in each directory from the already fetched files
			for (const file of files) {
				for (const dirPrefix of apiResponse.prefixes) {
					if (file.name.startsWith(dirPrefix) && file.name !== dirPrefix) {
						const dirPath = dirPrefix.replace(/\/$/, "");
						folderFileCountMap.set(
							dirPath,
							(folderFileCountMap.get(dirPath) || 0) + 1,
						);
					}
				}
			}

			// For more accurate count, we still need individual folder queries
			// But we can do them in parallel
			const folderCountPromises = dirPaths.map(async (dirPath) => {
				const dirPrefix = `${dirPath}/`;
				const [folderFiles] = await this.bucket.getFiles({
					prefix: dirPrefix,
				});
				return { dirPath, count: folderFiles.length };
			});

			const folderCounts = await Promise.all(folderCountPromises);
			folderCounts.forEach(({ dirPath, count }) => {
				folderFileCountMap.set(dirPath, count);
			});
		}

		// Process files
		for (const file of validFiles) {
			const bucketFile = StorageUtils.blobToFileInfo(file.metadata, gcpBaseUrl);
			const dbFile = dbFileMap.get(file.name);
			const fileInfo = StorageUtils.combineFileData(bucketFile, dbFile);
			items.push(fileInfo);
		}

		// Process directories (prefixes)
		if (apiResponse?.prefixes) {
			for (const dirPrefix of apiResponse.prefixes) {
				const dirPath = dirPrefix.replace(/\/$/, "");
				const dbDir = dbDirMap.get(dirPath);

				const bucketDir: Types.BucketDirectory = {
					path: dirPath,
					createdAt: new Date(),
					lastModified: new Date(),
					isPublic: dirPath.startsWith("public"),
				};

				const fileCount = folderFileCountMap.get(dirPath) || 0;
				const dirInfo = StorageUtils.combineDirectoryData(
					bucketDir,
					dbDir,
					fileCount,
				);
				items.push(dirInfo);
			}
		}

		// Apply search filter
		let filteredItems = items;
		if (input.searchTerm && input.searchTerm.length > 0) {
			const searchLower = input.searchTerm.toLowerCase();
			filteredItems = items.filter((item) =>
				item.name.toLowerCase().includes(searchLower),
			);
		}

		// Apply file type and content type filters
		filteredItems = StorageUtils.filterStorageItems(filteredItems, {
			includeDirectories: input.includeDirectories ?? null,
			fileType: input.fileType ?? null,
			fileTypes: input.fileTypes ?? null,
			contentTypes: input.contentTypes ?? null,
		});

		// Sort items
		const sortedItems = StorageUtils.sortItems(
			filteredItems,
			input.sortBy || Types.FileSortField.NAME,
			input.sortDirection || OrderSortDirection.ASC,
		);

		// Apply pagination
		const totalCount = sortedItems.length;
		const offset = input.offset || 0;
		const limit = input.limit || 50;
		const paginatedItems = sortedItems.slice(offset, offset + limit);
		const hasMore = offset + limit < totalCount;

		return {
			items: paginatedItems,
			totalCount,
			hasMore,
			offset,
			limit,
		};
	}

	async createFolder(
		input: Types.FolderCreateInput,
	): Promise<Types.FileOperationResult> {
		try {
			void StorageUtils.validatePath(input.path).then((err) => {
				if (err) throw new StorageValidationError(err);
			});

			const fullPath = cleanGcsPath(input.path);

			// Check parent directory permissions
			const parentPath = fullPath.substring(0, fullPath.lastIndexOf("/"));
			if (parentPath.length > 0) {
				const parentDir = await StorageDbRepository.directoryByPath(parentPath);
				if (parentDir && !parentDir.allowCreateSubDirs) {
					return {
						success: false,
						message: "Creating subdirectories not allowed in parent directory",
					};
				}
			}

			// Create folder marker in bucket
			const folderPath = `${fullPath}/`;
			const file = this.bucket.file(folderPath);
			await file.save("", {
				contentType: "application/x-directory",
			});

			// Only save folder in DB if custom permissions are provided
			const hasCustomPermissions =
				input.permissions != null ||
				input.protected === true ||
				input.protectChildren === true;

			let newDirectoryInfo: Types.DirectoryInfo;

			if (hasCustomPermissions) {
				try {
					const directoryEntity =
						await StorageDbRepository.createDirectory(input);

					const bucketDir: Types.BucketDirectory = {
						path: fullPath,
						createdAt: new Date(),
						lastModified: new Date(),
						isPublic: fullPath.startsWith("public"),
					};

					newDirectoryInfo = StorageUtils.combineDirectoryData(
						bucketDir,
						directoryEntity,
					);
				} catch (error) {
					// If DB operation fails, still return success since folder was created in bucket
					logger.warn(
						`Failed to save folder permissions in DB: ${error instanceof Error ? error.message : String(error)}`,
					);
					newDirectoryInfo = StorageUtils.createDirectoryFromPath(fullPath);
				}
			} else {
				newDirectoryInfo = StorageUtils.createDirectoryFromPath(fullPath);
			}

			return {
				success: true,
				message: "Folder created successfully",
				data: newDirectoryInfo,
			};
		} catch (error) {
			logger.error(`Failed to create folder: ${input.path}`, error);
			return {
				success: false,
				message: `Failed to create folder: ${error instanceof Error ? error.message : String(error)}`,
			};
		}
	}

	async renameFile(
		input: Types.FileRenameInput,
	): Promise<Types.FileOperationResult> {
		try {
			const pathErr = await StorageUtils.validatePath(input.currentPath);
			if (pathErr) {
				return {
					success: false,
					message: pathErr,
				};
			}

			const nameErr = await StorageUtils.validateFileName(input.newName);
			if (nameErr) {
				return {
					success: false,
					message: nameErr,
				};
			}

			const directoryPath = StorageUtils.extractDirectoryPath(
				input.currentPath,
			);

			const newPath = `${directoryPath}/${input.newName}`;

			// Copy to new location
			const sourceFile = this.bucket.file(input.currentPath);
			const destFile = this.bucket.file(newPath);
			await sourceFile.move(destFile);

			// Update database
			let fileEntity: Types.FileEntity | undefined;
			try {
				const dbFile = await StorageDbRepository.fileByPath(input.currentPath);
				if (dbFile) {
					const updatedFile = { ...dbFile, path: newPath };
					fileEntity = await StorageDbRepository.updateFile(updatedFile);
				}
			} catch {
				// Ignore DB update errors
			}

			const [metadata] = await destFile.getMetadata();
			const bucketFile = StorageUtils.blobToFileInfo(metadata, gcpBaseUrl);

			const fileInfo = StorageUtils.combineFileData(bucketFile, fileEntity);

			return {
				success: true,
				message: "File renamed successfully",
				data: fileInfo,
			};
		} catch (error) {
			logger.error(`Failed to rename file: ${input.currentPath}`, error);
			return {
				success: false,
				message: `Failed to rename file: ${error instanceof Error ? error.message : String(error)}`,
			};
		}
	}

	async deleteFile(path: string): Promise<Types.FileOperationResult> {
		try {
			const pathErr = await StorageUtils.validatePath(path);
			if (pathErr) {
				return {
					success: false,
					message: pathErr,
				};
			}

			// Check permissions and protection
			// Check if file is in use
			const usageCheck = await StorageDbRepository.checkFileUsage({
				path: path,
			});
			if (usageCheck.isInUse) {
				return {
					success: false,
					message: usageCheck.deleteBlockReason || "File is in use",
				};
			}

			// Check if the file is protected
			const dbFile = await StorageDbRepository.fileByPath(path);
			if (dbFile?.isProtected === true) {
				return {
					success: false,
					message: "File is protected from deletion",
				};
			}

			// Check parent directory permissions
			const parentPath = path.substring(0, path.lastIndexOf("/"));
			const parentDir = await StorageDbRepository.directoryByPath(parentPath);
			if (parentDir && !parentDir.allowDeleteFiles) {
				return {
					success: false,
					message: "File deletion not allowed in this directory",
				};
			}

			// Delete from bucket
			const file = this.bucket.file(path);
			await file.delete();

			// Delete from database
			try {
				await StorageDbRepository.deleteFile(path);
			} catch {
				// Ignore DB deletion errors
			}

			return {
				success: true,
				message: "File deleted successfully",
			};
		} catch (error) {
			logger.error(`Failed to delete file: ${path}`, error);
			return {
				success: false,
				message: `Failed to delete file: ${error instanceof Error ? error.message : String(error)}`,
			};
		}
	}

	async directoryInfoByPath(path: string): Promise<Types.DirectoryInfo | null> {
		// Check database first
		const dbDirectory = await StorageDbRepository.directoryByPath(path);

		// Check bucket
		const folderPath = `${path}/`;
		const [files] = await this.bucket.getFiles({
			prefix: folderPath,
			maxResults: 1,
		});

		const folderExists = files.length > 0;

		if (!folderExists && !dbDirectory) {
			return null;
		}

		const bucketDir: Types.BucketDirectory = {
			path,
			createdAt: new Date(),
			lastModified: new Date(),
			isPublic: path.startsWith("public"),
		};

		return StorageUtils.combineDirectoryData(bucketDir, dbDirectory);
	}

	async fileInfoByPath(path: string): Promise<Types.FileInfo | null> {
		try {
			const file = this.bucket.file(path);
			const [exists] = await file.exists();

			if (!exists) {
				return null;
			}

			const [metadata] = await file.getMetadata();
			const bucketFile = StorageUtils.blobToFileInfo(metadata, gcpBaseUrl);
			const dbFile = await StorageDbRepository.fileByPath(path);

			return StorageUtils.combineFileData(bucketFile, dbFile);
		} catch (error) {
			logger.error(`Failed to get file info: ${path}`, error);
			return null;
		}
	}

	async fileInfoByDbFileId(id: bigint): Promise<Types.FileInfo | null> {
		try {
			const dbFile = await StorageDbRepository.fileById(id);
			if (!dbFile) {
				return null;
			}

			const file = this.bucket.file(dbFile.path);
			const [exists] = await file.exists();

			if (!exists) {
				return null;
			}

			const [metadata] = await file.getMetadata();
			const bucketFile = StorageUtils.blobToFileInfo(metadata, gcpBaseUrl);

			return StorageUtils.combineFileData(bucketFile, dbFile);
		} catch (error) {
			logger.error(`Failed to get file info by id: ${id}`, error);
			return null;
		}
	}

	async storageStatistics(path?: string): Promise<Types.StorageStats> {
		try {
			const prefix = path ? `${path}/` : "";
			const [files] = await this.bucket.getFiles({ prefix });

			let totalSize = BigInt(0);
			const fileTypeMap = new Map<
				Types.FileTypes,
				{ count: number; size: bigint }
			>();

			for (const file of files) {
				const size = BigInt(file.metadata.size || 0);
				totalSize += size;

				const fileType = StorageUtils.getFileTypeFromContentType(
					file.metadata.contentType,
				);
				const current = fileTypeMap.get(fileType) || {
					count: 0,
					size: BigInt(0),
				};
				fileTypeMap.set(fileType, {
					count: current.count + 1,
					size: current.size + size,
				});
			}

			const fileTypeBreakdown = Array.from(fileTypeMap.entries()).map(
				([type, data]) => ({
					type,
					count: data.count,
					size: data.size,
				}),
			);

			// Count directories
			const response: GetFilesResponse = await this.bucket.getFiles({
				prefix,
				delimiter: "/",
			});
			const apiResponse = response[2] as GcsApiResponse | undefined;
			const directoryCount = apiResponse?.prefixes?.length || 0;

			return {
				totalFiles: files.length,
				totalSize,
				fileTypeBreakdown,
				directoryCount,
			};
		} catch (error) {
			logger.error("Failed to get storage statistics", error);
			return {
				totalFiles: 0,
				totalSize: BigInt(0),
				fileTypeBreakdown: [],
				directoryCount: 0,
			};
		}
	}

	async fetchDirectoryChildren(path?: string): Promise<Types.DirectoryInfo[]> {
		// Clean path, default to "public" if empty
		const searchPath =
			!path || path.length === 0 ? "public" : cleanGcsPath(path);
		const prefix = cleanGcsPath(searchPath, true);

		// Get directories from database
		const dbDirectories =
			await StorageDbRepository.directoriesByParentPath(searchPath);
		const dbDirectoriesByPath = new Map(
			dbDirectories.map((dir) => [dir.path, dir]),
		);

		// Get directories from bucket
		const responseData: GetFilesResponse = await this.bucket.getFiles({
			prefix,
			delimiter: "/",
			autoPaginate: false,
		});

		const directories: Types.DirectoryInfo[] = [];
		const apiResponse = responseData[2] as GcsApiResponse | undefined;

		if (apiResponse?.prefixes) {
			for (const dirPrefix of apiResponse.prefixes) {
				const dirPath = dirPrefix.replace(/\/$/, "");
				const dbDir = dbDirectoriesByPath.get(dirPath);

				const bucketDir: Types.BucketDirectory = {
					path: dirPath,
					createdAt: new Date(),
					lastModified: new Date(),
					isPublic: dirPath.startsWith("public"),
				};

				directories.push(StorageUtils.combineDirectoryData(bucketDir, dbDir));
			}
		}

		return directories;
	}

	async moveItems(
		input: Types.StorageItemsMoveInput,
	): Promise<Types.BulkOperationResult> {
		let successCount = 0;
		let failureCount = 0;
		const failures: Array<{ path: string; error: string }> = [];
		const successfulItems: Array<Types.FileInfo | Types.DirectoryInfo> = [];

		// Batch check if all source files exist in bucket
		const sourceExistenceChecks = await Promise.all(
			input.sourcePaths.map(async (sourcePath) => {
				const sourceFile = this.bucket.file(sourcePath);
				const [exists] = await sourceFile.exists();
				return { path: sourcePath, exists };
			}),
		);

		// Filter out non-existent sources
		const validSources = sourceExistenceChecks
			.filter((check) => {
				if (!check.exists) {
					failureCount++;
					failures.push({
						path: check.path,
						error: "Source path not found",
					});
					return false;
				}
				return true;
			})
			.map((check) => check.path);

		if (validSources.length === 0) {
			return {
				success: failureCount === 0,
				message: "No valid source files to move",
				successCount,
				failureCount,
				failures,
				successfulItems,
			};
		}

		// Batch load DB entities for source paths and directories
		const sourceDirectories = [
			...new Set(
				validSources.map((path) => path.substring(0, path.lastIndexOf("/"))),
			),
		];

		const [dbFiles, dbDirectories, dbSourceDirs, dbDestDir] = await Promise.all(
			[
				StorageDbRepository.filesByPaths(validSources),
				StorageDbRepository.directoriesByPaths(validSources),
				StorageDbRepository.directoriesByPaths(sourceDirectories),
				StorageDbRepository.directoryByPath(input.destinationPath),
			],
		);

		// Create lookup maps for O(1) access - fix the map creation
		const dbFileMap = new Map();
		dbFiles.forEach((file) => {
			if (file) {
				dbFileMap.set(file.path, file);
			}
		});

		const dbDirectoryMap = new Map();
		dbDirectories.forEach((dir) => {
			if (dir) {
				dbDirectoryMap.set(dir.path, dir);
			}
		});

		const dbSourceDirMap = new Map();
		dbSourceDirs.forEach((dir) => {
			if (dir) {
				dbSourceDirMap.set(dir.path, dir);
			}
		});

		// Check destination directory permissions once
		if (dbDestDir && !dbDestDir.allowUploads) {
			return {
				success: false,
				message: "Uploads not allowed to destination directory",
				successCount: 0,
				failureCount: validSources.length,
				failures: validSources.map((path) => ({
					path,
					error: "Uploads not allowed to destination directory",
				})),
				successfulItems,
			};
		}

		// Process each valid source
		for (const sourcePath of validSources) {
			try {
				// Check permissions for source directory
				const sourceDir = sourcePath.substring(0, sourcePath.lastIndexOf("/"));
				const dbSourceDir = dbSourceDirMap.get(sourceDir);
				if (dbSourceDir && !dbSourceDir.allowMove) {
					failureCount++;
					failures.push({
						path: sourcePath,
						error: `Move not allowed from directory: ${sourceDir}`,
					});
					continue;
				}

				// Perform the move in bucket (copy then delete)
				const fileName = StorageUtils.extractFileName(sourcePath);
				const newPath = `${input.destinationPath.replace(/\/$/, "")}/${fileName}`;

				const sourceFile = this.bucket.file(sourcePath);
				const destFile = this.bucket.file(newPath);
				await sourceFile.copy(destFile);
				await sourceFile.delete();

				// Update DB records - check if it's a file or directory and update accordingly
				const dbFile = dbFileMap.get(sourcePath);
				const dbDirectory = dbDirectoryMap.get(sourcePath);

				if (dbFile) {
					// Update file entity path
					await StorageDbRepository.updateFile({
						id: dbFile.id,
						path: newPath,
						isProtected: dbFile.isProtected,
					});

					// Get the updated file info for successful items
					const fileInfo = await this.fileInfoByPath(newPath);
					if (fileInfo) {
						successfulItems.push(fileInfo);
					}
				} else if (dbDirectory) {
					// Update directory entity path
					await StorageDbRepository.updateDirectory({
						...dbDirectory,
						path: newPath,
					});

					// Get the updated directory info for successful items
					const dirInfo = await this.directoryInfoByPath(newPath);
					if (dirInfo) {
						successfulItems.push(dirInfo);
					}
				} else {
					// No DB entity, get info from bucket
					const fileInfo = await this.fileInfoByPath(newPath);
					if (fileInfo) {
						successfulItems.push(fileInfo);
					}
				}

				successCount++;
			} catch (error) {
				failureCount++;
				failures.push({
					path: sourcePath,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}

		return {
			success: failureCount === 0,
			message:
				failureCount === 0
					? "All items moved successfully"
					: `${successCount} items moved, ${failureCount} failed`,
			successCount,
			failureCount,
			failures,
			successfulItems,
		};
	}

	async copyItems(
		input: Types.StorageItemsCopyInput,
	): Promise<Types.BulkOperationResult> {
		let successCount = 0;
		let failureCount = 0;
		const failures: Array<{ path: string; error: string }> = [];
		const successfulItems: Array<Types.FileInfo | Types.DirectoryInfo> = [];

		// Batch check if all source files exist in bucket
		const sourceExistenceChecks = await Promise.all(
			input.sourcePaths.map(async (sourcePath) => {
				const sourceFile = this.bucket.file(sourcePath);
				const [exists] = await sourceFile.exists();
				return { path: sourcePath, exists };
			}),
		);

		// Filter out non-existent sources
		const validSources = sourceExistenceChecks
			.filter((check) => {
				if (!check.exists) {
					failureCount++;
					failures.push({
						path: check.path,
						error: "Source path not found",
					});
					return false;
				}
				return true;
			})
			.map((check) => check.path);

		if (validSources.length === 0) {
			return {
				success: failureCount === 0,
				message: "No valid source files to copy",
				successCount,
				failureCount,
				failures,
				successfulItems,
			};
		}

		// Check destination directory permissions once
		const dbDestDir = await StorageDbRepository.directoryByPath(
			input.destinationPath,
		);
		if (dbDestDir && !dbDestDir.allowUploads) {
			return {
				success: false,
				message: "Uploads not allowed to destination directory",
				successCount: 0,
				failureCount: validSources.length,
				failures: validSources.map((path) => ({
					path,
					error: "Uploads not allowed to destination directory",
				})),
				successfulItems,
			};
		}

		// Process each valid source
		for (const sourcePath of validSources) {
			try {
				const fileName = StorageUtils.extractFileName(sourcePath);
				const destPath = `${input.destinationPath.replace(/\/$/, "")}/${fileName}`;

				// Copy file in bucket
				const sourceFile = this.bucket.file(sourcePath);
				const destFile = this.bucket.file(destPath);
				await sourceFile.copy(destFile);

				// Don't create DB entities as requested - just get file info from bucket
				const fileInfo = await this.fileInfoByPath(destPath);
				if (fileInfo) {
					successfulItems.push(fileInfo);
				}

				successCount++;
			} catch (error) {
				failureCount++;
				failures.push({
					path: sourcePath,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}

		return {
			success: failureCount === 0,
			message:
				failureCount === 0
					? "All items copied successfully"
					: `${successCount} items copied, ${failureCount} failed`,
			successCount,
			failureCount,
			failures,
			successfulItems,
		};
	}

	async deleteItems(
		input: Types.StorageItemsDeleteInput,
	): Promise<Types.BulkOperationResult> {
		let successCount = 0;
		let failureCount = 0;
		const failures: Array<{ path: string; error: string }> = [];
		const successfulItems: Array<Types.FileInfo | Types.DirectoryInfo> = [];

		// Batch load DB entities for all paths and their parent directories
		const parentDirectories = [
			...new Set(
				input.paths.map((path) => path.substring(0, path.lastIndexOf("/"))),
			),
		];

		const [dbFiles, dbDirectories, dbParentDirs, usageChecks] =
			await Promise.all([
				StorageDbRepository.filesByPaths(input.paths),
				StorageDbRepository.directoriesByPaths(input.paths),
				StorageDbRepository.directoriesByPaths(parentDirectories),
				// Batch check file usage if not force delete
				input.force
					? Promise.resolve([])
					: Promise.all(
							input.paths.map((path) =>
								StorageDbRepository.checkFileUsage({
									path: path,
								})
									.then((result) => ({ path, ...result }))
									.catch(() => ({
										path,
										isInUse: false,
										deleteBlockReason: null,
									})),
							),
						),
			]);

		// Create lookup maps for O(1) access
		const dbFileMap = new Map();
		dbFiles.forEach((file) => {
			if (file) {
				dbFileMap.set(file.path, file);
			}
		});

		const dbDirectoryMap = new Map();
		dbDirectories.forEach((dir) => {
			if (dir) {
				dbDirectoryMap.set(dir.path, dir);
			}
		});

		const dbParentDirMap = new Map();
		dbParentDirs.forEach((dir) => {
			if (dir) {
				dbParentDirMap.set(dir.path, dir);
			}
		});

		const usageCheckMap = new Map();
		usageChecks.forEach((check) => {
			usageCheckMap.set(check.path, check);
		});

		// Process each path
		for (const path of input.paths) {
			try {
				// Check if file is in use (unless force delete)
				if (!input.force) {
					const usageCheck = usageCheckMap.get(path);
					if (usageCheck?.isInUse) {
						failureCount++;
						failures.push({
							path,
							error: usageCheck.deleteBlockReason || "File is currently in use",
						});
						continue;
					}
				}

				// Check if file/directory is protected
				const dbFile = dbFileMap.get(path);
				const dbDirectory = dbDirectoryMap.get(path);

				if (dbFile?.isProtected === true || dbDirectory?.isProtected === true) {
					failureCount++;
					failures.push({
						path,
						error: "Item is protected from deletion",
					});
					continue;
				}

				// Check parent directory permissions
				const parentPath = path.substring(0, path.lastIndexOf("/"));
				const parentDir = dbParentDirMap.get(parentPath);
				if (parentDir) {
					const isFile = dbFile != null;
					const canDelete = isFile
						? parentDir.allowDeleteFiles
						: parentDir.allowDelete;
					if (!canDelete) {
						failureCount++;
						failures.push({
							path,
							error: "Deletion not allowed in parent directory",
						});
						continue;
					}
				}

				// Get entity before deleting for the result
				const fileEntity = await this.fileInfoByPath(path);
				const folderEntity = fileEntity
					? null
					: await this.directoryInfoByPath(path);

				// Delete from bucket
				const file = this.bucket.file(path);
				await file.delete();

				// Delete from database
				if (dbFile) {
					await StorageDbRepository.deleteFile(path);
					if (fileEntity) {
						successfulItems.push(fileEntity);
					}
				} else if (dbDirectory) {
					await StorageDbRepository.deleteDirectory(path);
					if (folderEntity) {
						successfulItems.push(folderEntity);
					}
				} else if (fileEntity) {
					// No DB entity, just add file to successful items
					successfulItems.push(fileEntity);
				} else if (folderEntity) {
					// No DB entity, just add folder to successful items
					successfulItems.push(folderEntity);
				}

				successCount++;
			} catch (error) {
				failureCount++;
				failures.push({
					path,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}

		return {
			success: failureCount === 0,
			message:
				failureCount === 0
					? "All items deleted successfully"
					: `${successCount} items deleted, ${failureCount} failed`,
			successCount,
			failureCount,
			failures,
			successfulItems,
		};
	}
}

export async function createGcpAdapter(): Promise<StorageService> {
	const storage = await createGcpStorage();
	return new GcpAdapter(storage);
}

import type { Dirent, Stats } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import crypto from "crypto";
import { SignedUrlRepository, StorageDbRepository } from "@/backend/db/repo";
import logger from "@/backend/lib/logger";
import { NEXT_PUBLIC_BASE_URL } from "@/backend/lib/server";
import * as Types from "@/backend/types";
import { StorageUtils } from "@/backend/utils";
import { extToMime } from "@/backend/utils/storage.utils";
import { OrderSortDirection } from "@/lib/enum";
import {
	STORAGE_CONFIG,
	type StorageService,
	StorageValidationError,
} from "./storage.service.interface";

/**
 * Clean path for local storage - removes leading slashes and normalizes
 */
function cleanLocalPath(inputPath: string): string {
	if (!inputPath || inputPath.length === 0) {
		return "";
	}

	// Remove leading slashes and trailing slashes
	const cleaned = inputPath.replace(/^\/+/, "").replace(/\/$/, "");

	return cleaned;
}

/**
 * Local filesystem storage adapter
 * Stores files in a configurable directory with signed URL support via API routes
 */
class LocalAdapter implements StorageService {
	private readonly basePath: string;
	private readonly baseUrl: string;

	constructor() {
		// Read environment variables in constructor for testability
		const storagePath = process.env.LOCAL_STORAGE_PATH || "./storage/";
		this.baseUrl = NEXT_PUBLIC_BASE_URL;
		this.basePath = path.resolve(process.cwd(), storagePath);
		logger.info(`Local storage initialized at: ${this.basePath}`);
	}

	// ============================================================================
	// Helper Methods
	// ============================================================================

	/**
	 * Convert relative user path to secure absolute filesystem path
	 * Prevents path traversal attacks
	 */
	private getAbsolutePath(relativePath: string): string {
		// Join the user path with base path and resolve it
		const resolvedPath = path.resolve(this.basePath, relativePath);

		// Check if resolved path is within base directory
		const relativeToBase = path.relative(this.basePath, resolvedPath);

		// If path starts with ".." or is absolute, it's trying to escape
		if (relativeToBase.startsWith("..") || path.isAbsolute(relativeToBase)) {
			throw new StorageValidationError("Path traversal detected");
		}

		return resolvedPath;
	}

	/**
	 * Create parent directories if needed
	 */
	private async ensureDirectory(dirPath: string): Promise<void> {
		await fs.mkdir(dirPath, { recursive: true, mode: 0o755 });
	}

	/**
	 * Calculate MD5 hash of a file
	 */
	private async calculateMd5(filePath: string): Promise<string> {
		const fileBuffer = await fs.readFile(filePath);
		const hash = crypto.createHash("md5").update(fileBuffer).digest("base64");
		return hash;
	}

	// ============================================================================
	// StorageService Interface Implementation
	// ============================================================================

	async fileExists(filePath: string): Promise<boolean> {
		try {
			const absolutePath = this.getAbsolutePath(filePath);
			await fs.access(absolutePath);
			const stats = await fs.stat(absolutePath);

			// Check if it's a file
			if (stats.isFile()) {
				// Check if file has a database record
				const dbFile = await StorageDbRepository.fileByPath(filePath);

				// If file exists on disk but not in DB, create a record
				if (!dbFile) {
					try {
						await StorageDbRepository.createFile(filePath, false);
						logger.info(
							`Created database record for existing file: ${filePath}`,
						);
					} catch (error) {
						logger.warn(
							`Failed to create database record for file: ${filePath}`,
							error,
						);
					}
				}

				return true;
			}

			// Check if it's a directory
			if (stats.isDirectory()) {
				// Check if directory has a database record
				const dbDirectory = await StorageDbRepository.directoryByPath(filePath);

				// If directory exists on disk but not in DB, it's okay - we don't auto-create directory records
				// unless they have custom permissions
				if (!dbDirectory) {
					logger.info(
						`Directory exists on disk without DB record: ${filePath}`,
					);
				}

				return true;
			}

			return false;
		} catch (error) {
			logger.error(`Error checking file existence: ${filePath}`, error);
			return false;
		}
	}

	async prepareUpload(
		input: Types.UploadPreparationInput,
	): Promise<Types.UploadPreparationResult> {
		try {
			// Clean the path
			const cleanedPath = cleanLocalPath(input.path);

			// The contentType is already a MIME type
			const mimeType = input.contentType;

			logger.info("🔍 [SERVER DEBUG] Preparing upload", {
				path: cleanedPath,
				fileSize: input.fileSize,
				contentType: mimeType,
				contentMd5: input.contentMd5,
			});

			// Validate upload
			const validationError = await StorageUtils.validateUpload(
				cleanedPath,
				input.fileSize,
				mimeType,
			);
			if (validationError) {
				throw new StorageValidationError(validationError);
			}

			// Optional lazy cleanup: clean up expired tokens before creating new one
			const cleanupStrategy = process.env.SIGNED_URL_CLEANUP_STRATEGY || "lazy";
			if (cleanupStrategy === "lazy" || cleanupStrategy === "both") {
				try {
					await SignedUrlRepository.deleteExpired();
				} catch (error) {
					// Non-fatal: log but don't block URL generation
					logger.error(
						"Lazy cleanup failed during signed URL generation",
						error,
					);
				}
			}

			// Generate unique token ID
			const tokenId = crypto.randomUUID();

			// Calculate expiration time
			const expiresAt = new Date(
				Date.now() + STORAGE_CONFIG.SIGNED_URL_DURATION * 60 * 1000,
			);

			// Create signed URL entry in database
			await SignedUrlRepository.createSignedUrl({
				id: tokenId,
				filePath: cleanedPath,
				contentType: mimeType,
				fileSize: BigInt(input.fileSize),
				contentMd5: input.contentMd5,
				expiresAt,
				createdAt: new Date(),
				used: false,
			});

			logger.info("🔍 [SERVER DEBUG] Stored signed URL in database", {
				tokenId,
				filePath: cleanedPath,
				storedContentType: mimeType,
				storedFileSize: input.fileSize,
				storedContentMd5: input.contentMd5,
				expiresAt,
			});

			// Return API route URL
			const signedUrl = `${this.baseUrl}/api/storage/upload/${tokenId}`;

			logger.info("Prepared upload successfully", {
				tokenId,
				path: cleanedPath,
				expiresAt,
				uploadType: Types.UploadType.SIGNED_URL,
			});

			return {
				id: tokenId,
				url: signedUrl,
				uploadType: Types.UploadType.SIGNED_URL,
			};
		} catch (error) {
			logger.error("Failed to prepare upload", {
				path: input.path,
				error: error instanceof Error ? error.message : String(error),
				stack: error instanceof Error ? error.stack : undefined,
			});
			throw error;
		}
	}

	async uploadFile(
		filePath: string,
		contentType: string,
		buffer: Buffer,
	): Promise<Types.FileUploadResult> {
		try {
			// Clean the file path
			const cleanedFilePath = cleanLocalPath(filePath);
			const fileSize = buffer.byteLength;

			// Validate upload
			const validationError = await StorageUtils.validateUpload(
				filePath,
				fileSize,
				contentType,
			);
			if (validationError) {
				return {
					success: false,
					message: validationError,
					data: null,
				};
			}

			// Check directory permissions
			const directoryPath = cleanedFilePath.substring(
				0,
				cleanedFilePath.lastIndexOf("/"),
			);
			const dbDirectory =
				await StorageDbRepository.directoryByPath(directoryPath);

			if (dbDirectory) {
				// Directory exists in DB, check permissions
				if (!dbDirectory.allowUploads) {
					return {
						success: false,
						message: "Uploads not allowed in this directory",
						data: null,
					};
				}
			}
			// If directory not in DB, allow upload (will be created automatically)

			// Write file to disk
			const absolutePath = this.getAbsolutePath(cleanedFilePath);
			await this.ensureDirectory(path.dirname(absolutePath));
			await fs.writeFile(absolutePath, buffer);

			// Create file entity in database
			logger.info("💾 uploadFile: Creating file entity in database", {
				filePath: cleanedFilePath,
			});
			const fileEntity = await StorageDbRepository.createFile(
				cleanedFilePath,
				false,
			);
			logger.info("💾 uploadFile: File entity created successfully", {
				fileEntity,
			});

			// Get file stats and create metadata
			const stats = await fs.stat(absolutePath);
			const md5Hash = await this.calculateMd5(absolutePath);

			const bucketFile: Types.BucketFile = {
				path: cleanedFilePath,
				directoryPath,
				size: BigInt(stats.size),
				contentType: contentType,
				md5Hash,
				createdAt: stats.birthtime,
				lastModified: stats.mtime,
				url: `${this.baseUrl}/api/storage/files/${cleanedFilePath}`,
				mediaLink: undefined,
				fileType: StorageUtils.getFileTypeFromContentType(contentType),
				isPublic: cleanedFilePath.startsWith("public"),
			};

			const fileInfo = StorageUtils.combineFileData(bucketFile, fileEntity);

			return {
				success: true,
				message: "File uploaded successfully",
				data: fileInfo,
			};
		} catch (error) {
			const errorPath = filePath; // Use original path for error logging
			logger.error(`Failed to upload file: ${errorPath}`, error);
			return {
				success: false,
				message: `Failed to upload file: ${error instanceof Error ? error.message : String(error)}`,
				data: null,
			};
		}
	}

	async listFiles(
		input: Types.FilesListSearchInput,
	): Promise<Types.StorageObjectList> {
		try {
			const searchPath = cleanLocalPath(input.path || "");
			const absolutePath = this.getAbsolutePath(searchPath);

			const items: Array<Types.FileInfo | Types.DirectoryInfo> = [];

			// Read directory contents
			let entries: Dirent[];
			try {
				entries = await fs.readdir(absolutePath, { withFileTypes: true });
			} catch {
				// Directory doesn't exist or not accessible
				return {
					items: [],
					totalCount: 0,
					hasMore: false,
					offset: input.offset || 0,
					limit: input.limit || 50,
				};
			}

			// Separate files and directories
			const filePaths: string[] = [];
			const dirPaths: string[] = [];

			for (const entry of entries) {
				const itemPath = searchPath
					? `${searchPath}/${entry.name}`
					: entry.name;
				if (entry.isFile()) {
					filePaths.push(itemPath);
				} else if (entry.isDirectory()) {
					dirPaths.push(itemPath);
				}
			}

			// Batch database queries
			const [dbFiles, dbDirectories] = await Promise.all([
				filePaths.length > 0 ? StorageDbRepository.filesByPaths(filePaths) : [],
				dirPaths.length > 0
					? StorageDbRepository.directoriesByPaths(dirPaths)
					: [],
			]);

			// Create lookup maps
			const dbFileMap = new Map();
			dbFiles.forEach((dbFile) => {
				if (dbFile) {
					dbFileMap.set(dbFile.path, dbFile);
				}
			});

			const dbDirMap = new Map();
			dbDirectories.forEach((dbDir) => {
				if (dbDir) {
					dbDirMap.set(dbDir.path, dbDir);
				}
			});

			// Process files
			for (const filePath of filePaths) {
				try {
					const absoluteFilePath = this.getAbsolutePath(filePath);
					const stats = await fs.stat(absoluteFilePath);
					const md5Hash = await this.calculateMd5(absoluteFilePath);
					const directoryPath = StorageUtils.extractDirectoryPath(filePath);

					// Detect content type from extension using shared utility
					const ext = path.extname(filePath).toLowerCase().slice(1); // Remove leading dot
					const contentType = extToMime[ext] || "application/octet-stream";

					const bucketFile: Types.BucketFile = {
						path: filePath,
						directoryPath,
						size: BigInt(stats.size),
						contentType,
						md5Hash,
						createdAt: stats.birthtime,
						lastModified: stats.mtime,
						url: `${this.baseUrl}/api/storage/files/${filePath}`,
						mediaLink: undefined,
						fileType: StorageUtils.getFileTypeFromContentType(contentType),
						isPublic: filePath.startsWith("public"),
					};

					const dbFile = dbFileMap.get(filePath);
					const fileInfo = StorageUtils.combineFileData(bucketFile, dbFile);
					items.push(fileInfo);
				} catch (error) {
					logger.warn(`Failed to process file: ${filePath}`, error);
				}
			}

			// Process directories
			for (const dirPath of dirPaths) {
				try {
					const absoluteDirPath = this.getAbsolutePath(dirPath);
					const stats = await fs.stat(absoluteDirPath);
					const dbDir = dbDirMap.get(dirPath);

					// Count files in directory
					let fileCount = 0;
					try {
						const dirEntries = await fs.readdir(absoluteDirPath);
						fileCount = dirEntries.length;
					} catch {
						fileCount = 0;
					}

					const bucketDir: Types.BucketDirectory = {
						path: dirPath,
						createdAt: stats.birthtime,
						lastModified: stats.mtime,
						isPublic: dirPath.startsWith("public"),
					};

					const dirInfo = StorageUtils.combineDirectoryData(
						bucketDir,
						dbDir,
						fileCount,
					);
					items.push(dirInfo);
				} catch (error) {
					logger.warn(`Failed to process directory: ${dirPath}`, error);
				}
			}

			// Apply search filter
			let filteredItems = items;
			if (input.searchTerm && input.searchTerm.length > 0) {
				const searchLower = input.searchTerm.toLowerCase();
				filteredItems = items.filter((item) =>
					item.name.toLowerCase().includes(searchLower),
				);
			}

			logger.info("[LocalAdapter] filteredItems", { filteredItems });
			// Apply file type and content type filters
			filteredItems = StorageUtils.filterStorageItems(filteredItems, {
				includeDirectories: input.includeDirectories ?? null,
				fileType: input.fileType ?? null,
				fileTypes: input.fileTypes ?? null,
				contentTypes: input.contentTypes ?? null,
			});

			// Sort items
			const sortedItems = StorageUtils.sortItems(
				filteredItems,
				input.sortBy || Types.FileSortField.NAME,
				input.sortDirection || OrderSortDirection.ASC,
			);

			// Apply pagination
			const totalCount = sortedItems.length;
			const offset = input.offset || 0;
			const limit = input.limit || 50;
			const paginatedItems = sortedItems.slice(offset, offset + limit);
			const hasMore = offset + limit < totalCount;

			return {
				items: paginatedItems,
				totalCount,
				hasMore,
				offset,
				limit,
			};
		} catch (error) {
			logger.error(`Failed to list files: ${input.path}`, error);
			return {
				items: [],
				totalCount: 0,
				hasMore: false,
				offset: input.offset || 0,
				limit: input.limit || 50,
			};
		}
	}

	async createFolder(
		input: Types.FolderCreateInput,
	): Promise<Types.FileOperationResult> {
		try {
			// Clean the path to remove leading/trailing slashes
			const fullPath = cleanLocalPath(input.path);

			// Validate path
			const validationError = await StorageUtils.validatePath(fullPath);
			if (validationError) {
				throw new StorageValidationError(validationError);
			}

			// Check parent directory permissions
			const parentPath = fullPath.substring(0, fullPath.lastIndexOf("/"));
			if (parentPath.length > 0) {
				const parentDir = await StorageDbRepository.directoryByPath(parentPath);
				if (parentDir && !parentDir.allowCreateSubDirs) {
					return {
						success: false,
						message: "Creating subdirectories not allowed in parent directory",
					};
				}
			}

			// Create folder in filesystem
			const absolutePath = this.getAbsolutePath(fullPath);
			await fs.mkdir(absolutePath, { recursive: true, mode: 0o755 });

			// Only save folder in DB if custom permissions are provided
			const hasCustomPermissions =
				input.permissions != null ||
				input.protected === true ||
				input.protectChildren === true;

			let newDirectoryInfo: Types.DirectoryInfo;

			if (hasCustomPermissions) {
				try {
					// Create directory with cleaned path
					const directoryEntity = await StorageDbRepository.createDirectory({
						...input,
						path: fullPath,
					});

					const bucketDir: Types.BucketDirectory = {
						path: fullPath,
						createdAt: new Date(),
						lastModified: new Date(),
						isPublic: fullPath.startsWith("public"),
					};

					newDirectoryInfo = StorageUtils.combineDirectoryData(
						bucketDir,
						directoryEntity,
					);
				} catch (error) {
					// If DB operation fails, still return success since folder was created
					logger.warn(
						`Failed to save folder permissions in DB: ${error instanceof Error ? error.message : String(error)}`,
					);
					newDirectoryInfo = StorageUtils.createDirectoryFromPath(fullPath);
				}
			} else {
				newDirectoryInfo = StorageUtils.createDirectoryFromPath(fullPath);
			}

			return {
				success: true,
				message: "Folder created successfully",
				data: newDirectoryInfo,
			};
		} catch (error) {
			logger.error(`Failed to create folder: ${input.path}`, error);
			return {
				success: false,
				message: `Failed to create folder: ${error instanceof Error ? error.message : String(error)}`,
			};
		}
	}

	async renameFile(
		input: Types.FileRenameInput,
	): Promise<Types.FileOperationResult> {
		try {
			// Validate current path
			const pathValidationError = await StorageUtils.validatePath(
				input.currentPath,
			);
			if (pathValidationError) {
				return {
					success: false,
					message: pathValidationError,
				};
			}

			// Validate new name
			const nameValidationError = await StorageUtils.validateFileName(
				input.newName,
			);
			if (nameValidationError) {
				return {
					success: false,
					message: nameValidationError,
				};
			}

			const directoryPath = StorageUtils.extractDirectoryPath(
				input.currentPath,
			);
			const newPath = `${directoryPath}/${input.newName}`;

			// Rename file in filesystem
			const currentAbsolutePath = this.getAbsolutePath(input.currentPath);
			const newAbsolutePath = this.getAbsolutePath(newPath);

			// Ensure target directory exists
			await this.ensureDirectory(path.dirname(newAbsolutePath));

			await fs.rename(currentAbsolutePath, newAbsolutePath);

			// Update database
			let fileEntity: Types.FileEntity | undefined;
			try {
				const dbFile = await StorageDbRepository.fileByPath(input.currentPath);
				if (dbFile) {
					const updatedFile = { ...dbFile, path: newPath };
					fileEntity = await StorageDbRepository.updateFile(updatedFile);
				}
			} catch (error) {
				logger.warn(
					`Failed to update file in database: ${input.currentPath}`,
					error,
				);
			}

			// Get file stats and create metadata
			const stats = await fs.stat(newAbsolutePath);
			const md5Hash = await this.calculateMd5(newAbsolutePath);

			// Detect content type from file extension using shared utility
			const ext = path.extname(newPath).toLowerCase().slice(1); // Remove leading dot
			const contentType = extToMime[ext] || "application/octet-stream";

			const bucketFile: Types.BucketFile = {
				path: newPath,
				directoryPath,
				size: BigInt(stats.size),
				contentType,
				md5Hash,
				createdAt: stats.birthtime,
				lastModified: stats.mtime,
				url: `${this.baseUrl}/api/storage/files/${newPath}`,
				mediaLink: undefined,
				fileType: StorageUtils.getFileTypeFromContentType(contentType),
				isPublic: newPath.startsWith("public"),
			};
			const fileInfo = StorageUtils.combineFileData(bucketFile, fileEntity);

			return {
				success: true,
				message: "File renamed successfully",
				data: fileInfo,
			};
		} catch (error) {
			logger.error(`Failed to rename file: ${input.currentPath}`, error);
			return {
				success: false,
				message: `Failed to rename file: ${error instanceof Error ? error.message : String(error)}`,
			};
		}
	}

	async deleteFile(filePath: string): Promise<Types.FileOperationResult> {
		try {
			// Validate path
			const validationError = await StorageUtils.validatePath(filePath);
			if (validationError) {
				return {
					success: false,
					message: validationError,
				};
			}

			// Check if file is in use
			const usageCheck = await StorageDbRepository.checkFileUsage({
				path: filePath,
			});

			if (usageCheck.isInUse) {
				return {
					success: false,
					message: usageCheck.deleteBlockReason || "File is in use",
				};
			}

			// Check if the file is protected
			const dbFile = await StorageDbRepository.fileByPath(filePath);
			if (dbFile?.isProtected === true) {
				return {
					success: false,
					message: "File is protected from deletion",
				};
			}

			// Check parent directory permissions
			const parentPath = filePath.substring(0, filePath.lastIndexOf("/"));
			const parentDir = await StorageDbRepository.directoryByPath(parentPath);
			if (parentDir && !parentDir.allowDeleteFiles) {
				return {
					success: false,
					message: "File deletion not allowed in this directory",
				};
			}

			// Delete from filesystem
			const absolutePath = this.getAbsolutePath(filePath);
			await fs.unlink(absolutePath);

			// Delete from database
			try {
				await StorageDbRepository.deleteFile(filePath);
			} catch (error) {
				logger.warn(`Failed to delete file from database: ${filePath}`, error);
			}

			return {
				success: true,
				message: "File deleted successfully",
			};
		} catch (error) {
			logger.error(`Failed to delete file: ${filePath}`, error);
			return {
				success: false,
				message: `Failed to delete file: ${error instanceof Error ? error.message : String(error)}`,
			};
		}
	}

	async directoryInfoByPath(
		dirPath: string,
	): Promise<Types.DirectoryInfo | null> {
		try {
			// Check database first
			const dbDirectory = await StorageDbRepository.directoryByPath(dirPath);

			// Check filesystem
			const absolutePath = this.getAbsolutePath(dirPath);
			let dirExists = false;
			let stats: Stats | null = null;

			try {
				stats = await fs.stat(absolutePath);
				dirExists = stats.isDirectory();
			} catch {
				dirExists = false;
			}

			if (!dirExists && !dbDirectory) {
				return null;
			}

			const bucketDir: Types.BucketDirectory = {
				path: dirPath,
				createdAt: stats?.birthtime || new Date(),
				lastModified: stats?.mtime || new Date(),
				isPublic: dirPath.startsWith("public"),
			};

			return StorageUtils.combineDirectoryData(bucketDir, dbDirectory);
		} catch (error) {
			logger.error(`Failed to get directory info: ${dirPath}`, error);
			return null;
		}
	}

