export namespace StorageUtils {
	const PATH_PATTERN = /^[a-zA-Z0-9._/\- ()]+$/;
	export const validatePath = (path: string): Promise<string | null> => {
		let err: string | null = null;
		if (!path || path.trim().length === 0) {
			err = "Path cannot be empty";
		}
		if (path.includes("..") || path.includes("//")) {
			err = "Path contains invalid directory traversal patterns";
		}
		if (!PATH_PATTERN.test(path)) {
			err = "Path contains invalid characters";
		}
		if (path.length > 1024) {
			err = "Path is too long (max 1024 characters)";
		}
		return Promise.resolve(err);
	};

	// Allow common file name characters: letters, numbers, spaces, parentheses, brackets, underscores, hyphens, periods
	const FILE_NAME_PATTERN = /^[a-zA-Z0-9._\-\s()[\]]+$/;
	export const validateFileName = (
		fileName: string,
	): Promise<string | null> => {
		let err: string | null = null;
		if (!fileName || fileName.trim().length === 0) {
			err = "File name cannot be empty";
		}
		if (!FILE_NAME_PATTERN.test(fileName)) {
			err = "File name contains invalid characters";
		}
		if (fileName.length > 255) {
			err = "File name is too long (max 255 characters)";
		}
		return Promise.resolve(err);
	};

	export const validateFileSize = (size: number): Promise<string | null> => {
		let err: string | null = null;
		if (size > STORAGE_CONFIG.MAX_FILE_SIZE) {
			err = `File size exceeds maximum allowed size (${STORAGE_CONFIG.MAX_FILE_SIZE / 1024 / 1024}MB)`;
		}
		return Promise.resolve(err);
	};

	export const validateUpload = async (
		path: string,
		size: number,
		contentType: string,
	): Promise<string | null> => {
		let error: string | null = null;

		const fileName = path.slice(path.lastIndexOf("/") + 1);
		void validateFileName(fileName).then((err) => {
			if (err) error = err;
		});

		void validatePath(path).then((err) => {
			if (err) error = err + "\n" + error;
		});

		void validateFileSize(size).then((err) => {
			if (err) error = err + "\n" + error;
		});

		if (!isAllowedMimeType(contentType)) {
			error = error + "\n" + contentType + " is not a allowed MIME type";
		}

		return Promise.resolve(error);
	};

	export const getFileTypeFromContentType = (
		contentType?: string,
	): Types.FileTypes => {
		if (!contentType) return Types.FileTypes.OTHER;

		if (contentType.startsWith("image/")) return Types.FileTypes.IMAGE;
		if (contentType.startsWith("video/")) return Types.FileTypes.VIDEO;
		if (contentType.startsWith("audio/")) return Types.FileTypes.AUDIO;
		if (
			contentType.includes("pdf") ||
			contentType.includes("document") ||
			contentType.includes("text")
		)
			return Types.FileTypes.DOCUMENT;
		if (contentType.includes("zip") || contentType.includes("rar"))
			return Types.FileTypes.ARCHIVE;

		// fonts
		if (contentType.includes("font")) return Types.FileTypes.FONT;

		return Types.FileTypes.OTHER;
	};

	export const extractDirectoryPath = (filePath: string): string => {
		const lastSlashIndex = filePath.lastIndexOf("/");
		return lastSlashIndex > 0 ? filePath.substring(0, lastSlashIndex) : "";
	};

	export const extractFileName = (filePath: string): string => {
		const lastSlashIndex = filePath.lastIndexOf("/");
		return lastSlashIndex >= 0
			? filePath.substring(lastSlashIndex + 1)
			: filePath;
	};

	export const sanitizePath = (path: string): string => {
		return path.replace(/\/+/g, "/").replace(/(?:^\/|\/(?=$))/g, "");
	};

	export const blobToFileInfo = (
		blob: Types.BlobMetadata,
		baseUrl: string,
	): Types.BucketFile => {
		const path = blob.name || "";
		const size = BigInt(blob.size || 0);
		const contentType = blob.contentType;
		const createdAt = blob.timeCreated
			? new Date(blob.timeCreated)
			: new Date();
		const lastModified = blob.updated ? new Date(blob.updated) : new Date();
		const url = `${baseUrl}${path}`;
		const mediaLink = blob.mediaLink;
		const fileType = getFileTypeFromContentType(contentType);
		const isPublic = path.startsWith("public");

		return {
			path,
			directoryPath: extractDirectoryPath(path),
			size,
			contentType,
			md5Hash: blob.md5Hash,
			createdAt,
			lastModified,
			url,
			mediaLink,
			fileType,
			isPublic,
		};
	};

	export const blobToDirectoryInfo = (
		blob: Types.BlobMetadata,
	): Types.BucketDirectory => {
		const path = (blob.name || "").replace(/\/$/, "");
		const createdAt = blob.timeCreated
			? new Date(blob.timeCreated)
			: new Date();
		const lastModified = blob.updated ? new Date(blob.updated) : new Date();
		const isPublic = path.startsWith("public");

		return {
			path,
			createdAt,
			lastModified,
			isPublic,
		};
	};

	export const combineDirectoryData = (
		bucketDir: Types.BucketDirectory,
		dbEntity?: Types.DirectoryEntity | null,
		fileCount: number = 0,
	): Types.DirectoryInfo => {
		const permissions: Types.DirectoryPermissions = dbEntity
			? {
					allowUploads: dbEntity.allowUploads,
					allowDelete: dbEntity.allowDelete,
					allowMove: dbEntity.allowMove,
					allowCreateSubDirs: dbEntity.allowCreateSubDirs,
					allowDeleteFiles: dbEntity.allowDeleteFiles,
					allowMoveFiles: dbEntity.allowMoveFiles,
				}
			: {
					allowUploads: true,
					allowDelete: true,
					allowMove: true,
					allowCreateSubDirs: true,
					allowDeleteFiles: true,
					allowMoveFiles: true,
				};

		const result: Types.DirectoryInfo = {
			dbId: dbEntity?.id,
			path: bucketDir.path,
			name: extractFileName(bucketDir.path),
			isProtected: dbEntity?.isProtected || false,
			permissions: permissions,
			protectChildren: dbEntity?.protectChildren || false,
			createdAt: bucketDir.createdAt,
			lastModified: bucketDir.lastModified,
			fileCount: fileCount,
			isFromBucket: true,
			isPublic: bucketDir.isPublic,
			// todo: implement following
			folderCount: 0,
			totalSize: 0,
		};
		return result;
	};

	export const combineFileData = (
		bucketFile: Types.BucketFile,
		dbEntity?: Types.FileEntity,
	): Types.FileInfo => {
		const usages: Types.FileUsageInfo[] = [];
		const isProtected = dbEntity?.isProtected || false;

		const result: Types.FileInfo = {
			dbId: dbEntity?.id,
			path: bucketFile.path,
			name: extractFileName(bucketFile.path),
			isProtected,
			directoryPath: bucketFile.directoryPath,
			size: bucketFile.size,
			contentType: bucketFile.contentType,
			md5Hash: bucketFile.md5Hash,
			createdAt: bucketFile.createdAt,
			lastModified: bucketFile.lastModified,
			url: bucketFile.url,
			mediaLink: bucketFile.mediaLink,
			fileType: bucketFile.fileType,
			isPublic: bucketFile.isPublic,
			isFromBucket: true,
			usages: usages,
			isInUse: usages.length > 0,
		};

		return result;
	};

	export const createDirectoryFromPath = (
		path: string,
	): Types.DirectoryInfo => {
		const now = new Date();
		const result: Types.DirectoryInfo = {
			path: path,
			name: extractFileName(path),
			isProtected: false,
			permissions: {
				allowUploads: true,
				allowDelete: true,
				allowMove: true,
				allowCreateSubDirs: true,
				allowDeleteFiles: true,
				allowMoveFiles: true,
			},
			protectChildren: false,
			createdAt: now,
			lastModified: now,
			fileCount: 0,
			isFromBucket: false,
			isPublic: path.startsWith("public"),
			// todo: implement following
			folderCount: 0,
			totalSize: 0,
		};

		return result;
	};

	/**
	 * Filter storage items by file types and content types
	 */
	export const filterStorageItems = (
		items: Array<Types.FileInfo | Types.DirectoryInfo>,
		filters: {
			includeDirectories?: boolean | null;
			fileType?: string | null;
			fileTypes?: string[] | null;
			contentTypes?: string[] | null;
		},
	): Array<Types.FileInfo | Types.DirectoryInfo> => {
		logger.info("[StorageUtils] filterStorageItems", { filters });
		logger.info("[StorageUtils] items", { items });
		const itemTypes = new Set<string>();

		let filtered = items;

		// Filter directories if includeDirectories is explicitly false
		if (filters.includeDirectories === false) {
			filtered = filtered.filter((item) => "fileType" in item);
		}

		// Filter by multiple file types (NEW)
		if (filters.fileTypes && filters.fileTypes.length > 0) {
			filtered = filtered.filter((item) => {
				if ("fileType" in item) {
					itemTypes.add(item.fileType);
					return filters.fileTypes?.includes(item.fileType);
				}
				// If includeDirectories is true, allow directories to pass through
				return filters.includeDirectories === true;
			});
		}

		// Filter by multiple content types (NEW)
		if (filters.contentTypes && filters.contentTypes.length > 0) {
			filtered = filtered.filter((item) => {
				if ("contentType" in item && item.contentType) {
					itemTypes.add(item.contentType);
					return filters.contentTypes?.includes(item.contentType);
				}
				// If includeDirectories is true, allow directories to pass through
				return filters.includeDirectories === true;
			});
		}

		// Keep backward compatibility with single fileType
		if (filters.fileType) {
			filtered = filtered.filter((item) => {
				if ("fileType" in item) {
					itemTypes.add(item.fileType);
					return item.fileType === filters.fileType;
				}
				// If includeDirectories is true, allow directories to pass through
				return filters.includeDirectories === true;
			});
		}

		logger.info("[StorageUtils] itemTypes", { itemTypes });

		logger.info("[StorageUtils] filtered", { filtered });

		return filtered;
	};

	export const sortItems = (
		items: Array<Types.FileInfo | Types.DirectoryInfo>,
		sortBy: Types.FileSortField,
		direction: OrderSortDirection,
	): Array<Types.FileInfo | Types.DirectoryInfo> => {
		const sorted = [...items].sort((a, b) => {
			let comparison = 0;

			switch (sortBy) {
				case Types.FileSortField.NAME:
					comparison = a.name.localeCompare(b.name);
					break;
				case Types.FileSortField.SIZE: {
					const sizeA = "size" in a ? Number(a.size) : 0;
					const sizeB = "size" in b ? Number(b.size) : 0;
					comparison = sizeA - sizeB;
					break;
				}
				case Types.FileSortField.TYPE: {
					const typeA = "fileType" in a ? a.fileType : "DIRECTORY";
					const typeB = "fileType" in b ? b.fileType : "DIRECTORY";
					comparison = typeA.localeCompare(typeB);
					break;
				}
				case Types.FileSortField.CREATED:
					comparison = a.createdAt.getTime() - b.createdAt.getTime();
					break;
				case Types.FileSortField.MODIFIED:
					comparison = a.lastModified.getTime() - b.lastModified.getTime();
					break;
			}

			return direction === OrderSortDirection.ASC ? comparison : -comparison;
		});

		return sorted;
	};
}

import {
	asc,
	desc,
	eq,
	gt,
	gte,
	isNull,
	like,
	lt,
	lte,
	not,
	notLike,
	or,
} from "drizzle-orm";
import type { PgSelect } from "drizzle-orm/pg-core";
import { fullTextSearch } from "@/backend/db/query.extensions";
import { students } from "@/backend/db/schema";
import * as Types from "@/backend/types";
import { OrderSortDirection } from "@/lib/enum";

export namespace StudentFilterUtils {
	export function applyFilters<T extends PgSelect>(
		qb: T,
		args?: Types.StudentFilterArgs | null,
	) {
		if (!args) return qb;
		const ftsLang = "simple"; // Use "simple" for language-agnostic, or "english", "arabic" etc.

		// Name filters
		if (args.name) {
			const ftsCondition = fullTextSearch(students.name, args.name, ftsLang);
			if (ftsCondition) {
				qb = qb.where(ftsCondition);
			}
		}
		if (args.nameNotContains) {
			qb = qb.where(notLike(students.name, `%${args.nameNotContains}%`));
		}
		if (args.nameEquals) {
			qb = qb.where(eq(students.name, args.nameEquals));
		}
		if (args.nameNotEquals) {
			qb = qb.where(not(eq(students.name, args.nameNotEquals)));
		}
		if (args.nameStartsWith) {
			qb = qb.where(like(students.name, `${args.nameStartsWith}%`));
		}
		if (args.nameEndsWith) {
			qb = qb.where(like(students.name, `%${args.nameEndsWith}`));
		}
		if (args.nameIsEmpty) {
			qb = qb.where(eq(students.name, ""));
		}
		if (args.nameIsNotEmpty) {
			qb = qb.where(not(eq(students.name, "")));
		}

		// Email filters (contains)
		if (args.email) {
			qb = qb.where(like(students.email, `%${args.email}%`));
		}
		if (args.emailNotContains) {
			qb = qb.where(notLike(students.email, `%${args.emailNotContains}%`));
		}
		if (args.emailEquals?.value) {
			qb = qb.where(eq(students.email, args.emailEquals.value));
		}
		if (args.emailNotEquals) {
			qb = qb.where(not(eq(students.email, args.emailNotEquals)));
		}
		if (args.emailStartsWith) {
			qb = qb.where(like(students.email, `${args.emailStartsWith}%`));
		}
		if (args.emailEndsWith) {
			qb = qb.where(like(students.email, `%${args.emailEndsWith}`));
		}
		if (args.emailIsEmpty) {
			qb = qb.where(or(eq(students.email, ""), isNull(students.email)));
		}
		if (args.emailIsNotEmpty) {
			qb = qb.where(not(isNull(students.email)));
		}

		// Phone number filter (contains)
		if (args.phoneNumber?.number) {
			qb = qb.where(like(students.phoneNumber, `%${args.phoneNumber.number}%`));
		}

		// Gender filter
		if (args.gender) {
			qb = qb.where(eq(students.gender, args.gender));
		}

		// Nationality filter
		if (args.nationality) {
			qb = qb.where(eq(students.nationality, args.nationality));
		}

		// Created at filters
		if (args.createdAt) {
			qb = qb.where(eq(students.createdAt, args.createdAt));
		}
		if (args.createdAtNot) {
			qb = qb.where(not(eq(students.createdAt, args.createdAtNot)));
		}
		if (args.createdAtFrom) {
			qb = qb.where(gte(students.createdAt, args.createdAtFrom));
		}
		if (args.createdAtTo) {
			qb = qb.where(lte(students.createdAt, args.createdAtTo));
		}
		if (args.createdAtAfter) {
			qb = qb.where(gt(students.createdAt, args.createdAtAfter));
		}
		if (args.createdAtBefore) {
			qb = qb.where(lt(students.createdAt, args.createdAtBefore));
		}
		if (args.createdAtOnOrAfter) {
			qb = qb.where(gte(students.createdAt, args.createdAtOnOrAfter));
		}
		if (args.createdAtOnOrBefore) {
			qb = qb.where(lte(students.createdAt, args.createdAtOnOrBefore));
		}
		if (args.createdAtIsEmpty) {
			qb = qb.where(isNull(students.createdAt));
		}
		if (args.createdAtIsNotEmpty) {
			qb = qb.where(not(isNull(students.createdAt)));
		}

		// Birthdate filters (dateOfBirth is Date)
		if (args.birthDate) {
			qb = qb.where(eq(students.dateOfBirth, args.birthDate));
		}
		if (args.birthDateNot) {
			qb = qb.where(not(eq(students.dateOfBirth, args.birthDateNot)));
		}
		if (args.birthDateFrom) {
			qb = qb.where(gte(students.dateOfBirth, args.birthDateFrom));
		}
		if (args.birthDateTo) {
			qb = qb.where(lte(students.dateOfBirth, args.birthDateTo));
		}
		if (args.birthDateAfter) {
			qb = qb.where(gt(students.dateOfBirth, args.birthDateAfter));
		}
		if (args.birthDateBefore) {
			qb = qb.where(lt(students.dateOfBirth, args.birthDateBefore));
		}
		if (args.birthDateOnOrAfter) {
			qb = qb.where(gte(students.dateOfBirth, args.birthDateOnOrAfter));
		}
		if (args.birthDateOnOrBefore) {
			qb = qb.where(lte(students.dateOfBirth, args.birthDateOnOrBefore));
		}
		if (args.birthDateIsEmpty) {
			qb = qb.where(isNull(students.dateOfBirth));
		}
		if (args.birthDateIsNotEmpty) {
			qb = qb.where(not(isNull(students.dateOfBirth)));
		}

		return qb;
	}

	export function applyOrdering<T extends PgSelect>(
		qb: T,
		orderBy?: Types.StudentsOrderByClause[] | null,
	) {
		if (!orderBy || orderBy.length === 0) return qb;

		orderBy.forEach((clause) => {
			let column:
				| typeof students.id
				| typeof students.name
				| typeof students.email
				| typeof students.dateOfBirth
				| typeof students.gender
				| typeof students.createdAt;
			switch (clause.column) {
				case Types.StudentsOrderByColumn.ID:
					column = students.id;
					break;
				case Types.StudentsOrderByColumn.NAME:
					column = students.name;
					break;
				case Types.StudentsOrderByColumn.EMAIL:
					column = students.email;
					break;
				case Types.StudentsOrderByColumn.DATE_OF_BIRTH:
					column = students.dateOfBirth;
					break;
				case Types.StudentsOrderByColumn.GENDER:
					column = students.gender;
					break;
				case Types.StudentsOrderByColumn.CREATED_AT:
					column = students.createdAt;
					break;
				case Types.StudentsOrderByColumn.UPDATED_AT:
					column = students.updatedAt;
					break;
				default:
					return;
			}
			qb = qb.orderBy(
				clause.order === OrderSortDirection.ASC ? asc(column) : desc(column),
			);
		});
		return qb;
	}
}

import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { glob } from "glob";
import {
	ensureCacheDir,
	getCachedMtime,
	getCachedResult,
	getFileMtime,
	saveResult,
	updateCachedMtime,
} from "./cache";
import { COLORS, logError, logInfo, logSuccess, PROJECT_ROOT } from "./config";

export async function runHealthCheck(forceFull = false): Promise<void> {
	ensureCacheDir();

	logInfo("Finding all TypeScript files...");
	const files = await glob("src/**/*.{ts,tsx}", { cwd: PROJECT_ROOT });

	if (files.length === 0) {
		logError("No TypeScript files found in src/");
		return;
	}

	logInfo(`📊 Found ${files.length} TypeScript files`);

	const filesToCheck = files.filter((file) => {
		if (forceFull) return true;
		const currentMtime = getFileMtime(join(PROJECT_ROOT, file));
		const cachedMtime = getCachedMtime(file);
		return currentMtime !== cachedMtime;
	});

	if (filesToCheck.length === 0) {
		logSuccess("✨ All files are up to date (no changes detected)");
	} else {
		logInfo(`🔄 Checking ${filesToCheck.length} changed file(s)`);
		logInfo(
			`⚡ Skipping ${files.length - filesToCheck.length} unchanged file(s)`,
		);
	}

	let perfectCount = 0;
	let warningCount = 0;
	let errorCount = 0;
	let cachedCount = 0;
	const warningFiles: string[] = [];
	const errorFiles: string[] = [];

	for (const file of files) {
		const isChanged = filesToCheck.includes(file);
		const filePath = join(PROJECT_ROOT, file);

		if (isChanged) {
			const result = spawnSync("cs", ["check", filePath], { encoding: "utf8" });
			const output = result.stdout + result.stderr;

			if (output.includes("warn:")) {
				warningCount++;
				warningFiles.push(file);
				globalThis.console.log(`${COLORS.YELLOW}⚠️  ${file}${COLORS.NC}`);
				const warnings = output
					.split("\n")
					.filter((line) => line.includes("warn:"))
					.map((l) => `    ${l.trim()}`)
					.join("\n");
				globalThis.console.log(warnings);
				saveResult(file, "warning", warnings);
			} else if (output.includes("error:")) {
				errorCount++;
				errorFiles.push(file);
				globalThis.console.log(`${COLORS.RED}❌ ${file}${COLORS.NC}`);
				const errors = output
					.split("\n")
					.filter((line) => line.includes("error:"))
					.map((l) => `    ${l.trim()}`)
					.join("\n");
				globalThis.console.log(errors);
				saveResult(file, "error", errors);
			} else {
				perfectCount++;
				globalThis.console.log(`${COLORS.GREEN}✅ ${file}${COLORS.NC}`);
				saveResult(file, "perfect", "");
			}
			updateCachedMtime(file, getFileMtime(filePath));
		} else {
			const cached = getCachedResult(file);
			if (cached) {
				if (cached.status === "perfect") {
					perfectCount++;
				} else if (cached.status === "warning") {
					warningCount++;
					warningFiles.push(file);
					globalThis.console.log(`${COLORS.YELLOW}⚠️  ${file}${COLORS.NC}`);
					if (cached.details) globalThis.console.log(cached.details);
				} else if (cached.status === "error") {
					errorCount++;
					errorFiles.push(file);
					globalThis.console.log(`${COLORS.RED}❌ ${file}${COLORS.NC}`);
					if (cached.details) globalThis.console.log(cached.details);
				}
			}
			cachedCount++;
		}
	}

	printSummary(
		perfectCount,
		warningCount,
		errorCount,
		cachedCount,
		warningFiles,
		errorFiles,
	);

	if (errorCount > 0 || warningCount > 0) {
		process.exit(1);
	}
}

function printSummary(
	perfect: number,
	warning: number,
	error: number,
	cached: number,
	warningFiles: string[],
	errorFiles: string[],
): void {
	globalThis.console.log("");
	globalThis.console.log(
		"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
	);
	globalThis.console.log("📈 Code Health Summary");
	globalThis.console.log(
		"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
	);
	globalThis.console.log(
		`${COLORS.GREEN}✅ Perfect health: ${perfect} files${COLORS.NC}`,
	);
	globalThis.console.log(
		`${COLORS.YELLOW}⚠️  With warnings: ${warning} files${COLORS.NC}`,
	);
	globalThis.console.log(
		`${COLORS.RED}❌ With errors: ${error} files${COLORS.NC}`,
	);
	if (cached > 0) {
		globalThis.console.log(
			`${COLORS.BLUE}⚡ Cached results: ${cached} files${COLORS.NC}`,
		);
	}
	globalThis.console.log(
		"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
	);

	if (warningFiles.length > 0) {
		globalThis.console.log(
			`\n${COLORS.YELLOW}Files with warnings:${COLORS.NC}`,
		);
		warningFiles.forEach((f) => {
			globalThis.console.log(`  - ${f}`);
		});
	}

	if (errorFiles.length > 0) {
		globalThis.console.log(`\n${COLORS.RED}Files with errors:${COLORS.NC}`);
		errorFiles.forEach((f) => {
			globalThis.console.log(`  - ${f}`);
		});
	}
}
